import { BrowserWindow, IpcMainInvokeEvent, app, ipcMain, screen } from "electron";
import { _PuppeteerService, PuppeteerService } from "../PuppeteerService";
import { Account } from "src/models/Account";
import { join } from "path";
import fs from "node:fs";
import { LaunchOptions, Page } from "puppeteer";
import { sendRequest } from "../../requestHandlers";
import accountRepository from "../../../database/repository/account.repository";
import AppUtils from "../../../utils";
import proxyRepository from "../../../database/repository/proxy.repository";
import { Proxy } from "src/models/Proxy";
import { settingRepository } from "../../../database/repository/setting.repository";
import { appCoreService } from "../../../services/appCoreService";

interface ICreateBrowserFacebook {
    browserId: string;
    userDataDir: string | undefined;
    proxy?: Proxy;
    headless?: boolean;
}

export class _FacebookPuppeteer {

    constructor(
        private puppeteerService: _PuppeteerService
    ) {}

    private async getCode2fa(code2fa: string) {
        const { body } = await sendRequest({ url: `https://2fa.live/tok/${code2fa}` })
        const data = JSON.parse(body)
        if (!data.token) {
            throw new Error('Không tìm thấy token');
        }
        return data.token;
    }

    private async prepareArgs(args: string[]) {
        const size = screen.getPrimaryDisplay().workAreaSize;
        let result = [
            ...args,
            '--window-size=' + size.width + ',' + size.height
        ]
        const settingEnableSound = await settingRepository.getSettingByKey('puppeteer.enableSound');
        if (settingEnableSound && settingEnableSound.value === 'true') {
            // loại bỏ tuỳ chọn Tắt âm thanh nếu user cài đặt bật
            result = result.filter(val => val !== '--mute-audio');
        }
        return result;
    }

    private async getArgs() {
        const settingArgs = await settingRepository.getSettingByKey('puppeteer.args');
        if (settingArgs) {
            const args = settingArgs.value.split(',').map(arg => arg.trim());
            return await this.prepareArgs(args);
        }
        const args: string[] = [
            '--disable-blink-features=AutomationControlled', // Loại bỏ flag "enable-automation" để tránh bị phát hiện là bot
            '--disable-notifications', // Tắt thông báo
            // ← Bỏ qua lỗi HTTPS
            '--ignore-certificate-errors',
            '--allow-running-insecure-content',
            // // ← Các flag để tăng hiệu suất và tránh lỗi hệ thống
            '--disable-gpu',
            '--disable-dev-shm-usage',
            '--no-sandbox',
            '--disable-setuid-sandbox',
            '--disable-software-rasterizer',
            '--disable-application-cache',
            // ← Tắt các cảnh báo không cần thiết
            '--disable-logging',
            '--log-level=2',
            '--disable-infobars',
            // ← Tắt kiểm tra an toàn của Chrome
            '--safebrowsing-disable-extension-blacklist',
            '--safebrowsing-disable-download-protection',
            '--autoplay-policy=no-user-gesture-required', // ← Tự động chạy video/audio không cần thao tác tay
            '--mute-audio', // ← Tắt âm thanh
            // ← Thêm các flag để tránh timeout
            '--disable-background-timer-throttling',
            '--disable-backgrounding-occluded-windows',
            '--disable-renderer-backgrounding',
            '--disable-features=TranslateUI',
            '--disable-ipc-flooding-protection',
        ]
        return await this.prepareArgs(args);
    }

    private async createBrowserFacebook({ browserId, userDataDir, proxy, headless = true }: ICreateBrowserFacebook, callbackPageId?: (pageId: string) => void) {
        const pageId = this.puppeteerService.createPageId(browserId);
        try {
            this.puppeteerService.setInitPageId(pageId);
            callbackPageId?.(pageId);
            let executablePath: string;
            const settingChromePath = await settingRepository.getSettingByKey('puppeteer.chromePath');
            if (settingChromePath) {
                if (!fs.existsSync(settingChromePath.value)) {
                    throw new Error(`Không tìm thấy file chrome tại đường dẫn: ${settingChromePath.value}`);
                }
                executablePath = settingChromePath.value;
            } else {
                executablePath = await AppUtils.getSystemChromePath();
            }
            if (userDataDir) {
                fs.mkdirSync(userDataDir, { recursive: true });
            }
            const args = await this.getArgs();
            appCoreService.logDebug("args: " + JSON.stringify(args));
            if (proxy) {
                args.push(`--proxy-server=http://${proxy.ip}:${proxy.port}`);
            }
            const options: LaunchOptions = {
                headless,
                executablePath,
                args,
                defaultViewport: null,
                // ignoreDefaultArgs: ['--enable-automation', '--enable-logging'], // Lỗi trên win
                userDataDir,
                timeout: 120000,
                protocolTimeout: 180000,
            }
            const { browser, page } = await this.puppeteerService.createBrowser(options, browserId, pageId, proxy);
            await this.puppeteerService.gotoUrl(pageId, 'https://www.facebook.com/?locale=en_EN');
            return { browser, page, pageId };
        } catch (error: any) {
            this.puppeteerService.removePageIdInit(pageId);
            throw error;
        }
    }

    public async openChromeByAccount(account: Account): Promise<void> {
        let interval: NodeJS.Timeout | undefined;
        const browserId = account.id.toString();
        const browser = this.puppeteerService.browserMap.get(browserId);
        if (browser) {
            throw new Error('Tài khoản này đang có tiến trình chạy vui lòng dừng hết tiến trình của tài khoản để mở chrome!');
        }
        let userDataDir = account.pathProfile;
        if (!userDataDir) {
            userDataDir = join(app.getPath('userData'), 'Profile', account.userId);
        }
        const { browser: browserNew, page, pageId } = await this.createBrowserFacebook({
            browserId,
            userDataDir,
            proxy: account.proxy,
            headless: false
        });
        let dataFbDtsgRev = null;
        try {
            debugger;
            dataFbDtsgRev = await this.loginFacebook(page, account, pageId);
        } catch (error) {
            debugger;
            console.log("Lỗi đăng nhập", error)
        }
        debugger;
        return new Promise<void>(async (resolve) => {
            let isCheck = true;
            browserNew.on('disconnected', () => {
                clearInterval(interval);
                isCheck = false;
                resolve();
            });
            while (isCheck) {
                try {
                    const currentUrl = page.url();
                    if (!currentUrl.includes('facebook.com')) {
                        await AppUtils.sleep(5000);
                        continue;
                    }
                    if (!dataFbDtsgRev && currentUrl.includes('/two_factor/') && account.code2fa) {
                        // Nếu gặp url bắt nhập mã 2fa thì nhập mã 2fa
                        await this.inputCode2fa(page, account.code2fa);
                    }
                    const { fbdtsg, rev } = await this.getFbInitData(page);
                    if (!fbdtsg || !rev) {
                        await AppUtils.sleep(5000);
                        continue;
                    }
                    // Nếu trạng thái vẫn là đăng nhập thành công thì lưu cookie
                    await this.saveNewCookieAccountFb(page, account);
                    break;
                } catch (error) {}
            }
        })
    }
    public async closeChromeByAccount(account: Account): Promise<void> {
        const browserId = account.id.toString();
        const browser = this.puppeteerService.browserMap.get(browserId);
        if (!browser) {
            throw new Error('Tài khoản này đang có trạng thái không mở chrome!');
        }
        await browser.close();
    }

    private async getProxyByAccount(account: Account): Promise<Proxy | undefined> {
        let proxy: Proxy | undefined = account.proxy;
        if (account.typeAccount === 'Fanpage') {
            const proxyEntity = await proxyRepository.getProxyByAccountId(account.id);
            if (proxyEntity) {
                proxy = Proxy.map(proxyEntity);
            }
        }
        return proxy;
    }
    private async getUserDataDirByAccount(account: Account): Promise<string | undefined> {
        let userDataDir = account.pathProfile;
        if (!userDataDir) {
            if (account.typeAccount === 'Fanpage') {
                return undefined; // với fanpage sẽ không tạo thư mục profile (để puppeteer tự tạo và và tự xoá profile khi chạy xong)
            } else {
                userDataDir = join(app.getPath('userData'), 'Profile', account.userId);
            }
        }
        return userDataDir;
    }
    public async createPageFacebook(account: Account, callbackPageId: (pageId: string) => void): Promise<{ pageId: string, fbdtsg: string, rev: string, cookie: string }> {
        const browserId = account.id.toString();
        let browser = this.puppeteerService.browserMap.get(browserId);
        if (browser) {
            const pageId = this.puppeteerService.createPageId(browserId);
            try {
                this.puppeteerService.setInitPageId(pageId);
                callbackPageId(pageId);
                const { page } = await this.puppeteerService.createPage(browserId, pageId);
                await this.puppeteerService.gotoUrl(page, 'https://www.facebook.com/?locale=en_EN');
                const { fbdtsg, rev } = await this.handleGetFbInitData(page, pageId);
                const cookie = await this.puppeteerService.getRawCookies(page);
                return { pageId, fbdtsg, rev, cookie };
            } catch (error: any) {
                this.puppeteerService.removePageIdInit(pageId);
                throw error;
            }
        }
        // Lấy proxy
        const proxy: Proxy | undefined = await this.getProxyByAccount(account);
        const userDataDir = await this.getUserDataDirByAccount(account);
        const { browser: browserNew, page, pageId } = await this.createBrowserFacebook(
            { browserId, userDataDir, proxy },
            callbackPageId
        );
        try {
            let { fbdtsg, rev } = await this.loginFacebook(page, account, pageId);
            if (account.typeAccount === 'Fanpage') {
                const expirationDate = new Date();
                expirationDate.setDate(expirationDate.getDate() + 365);
                const expiresInSeconds = Math.floor(expirationDate.getTime() / 1000);
                await page.setCookie({
                    name: "i_user",
                    value: account.userId,
                    domain: ".facebook.com",
                    path: '/',
                    secure: false,
                    expires: expiresInSeconds
                });
                await this.puppeteerService.reloadPage(page);
                // Lấy lại fb_dtsg và rev sau khi đăng nhập thành công cho fanpage
                ({ fbdtsg, rev } = await this.handleGetFbInitData(page, pageId));
            }
            const cookie = await this.puppeteerService.getRawCookies(page);
            return { pageId, fbdtsg, rev, cookie };
        } catch (error: any) {
            await accountRepository.updateLiveAccount(account.id, 'Die');
            throw error;
        }
    }

    private async checkLogin(page: Page, account: Account): Promise<{ fbdtsg: string, rev: string } | undefined> {
        await this.puppeteerService.gotoUrl(page, 'https://www.facebook.com/?locale=en_EN');
        try {
            const emailInput = await page.$('input[name="email"]');
            const passInput = await page.$('input[name="pass"]');
            let loginButton: any = await page.$('button[name="login"]');
            if (!loginButton) {
                loginButton = await page.$('div[aria-label="Log In"]');
            }
            if (emailInput && passInput && loginButton) {
                return;
            }
            const { fbdtsg, rev } = await this.getFbInitData(page);
            if (!fbdtsg || !rev) {
                return;
            }
            // Nếu trạng thái vẫn là đăng nhập thành công thì lưu cookie
            await this.saveNewCookieAccountFb(page, account);
            return { fbdtsg, rev };
        } catch (error) {
            return undefined;
        }
    }

    private async loginFacebook(page: Page, account: Account, pageId: string): Promise<{ fbdtsg: string, rev: string }> {
        try {
            let accountLogin = account;
            if (account.typeAccount === 'Fanpage') {
                if (!account.userOwner) {
                    throw new Error('Không thể xác định chủ sở hữu tài khoản, vui lòng thử lại sau.');
                }
                accountLogin = account.userOwner;
            }
            const dataFbDtsgRev = await this.checkLogin(page, accountLogin);
            if (dataFbDtsgRev) {
                return dataFbDtsgRev;
            }
            // Login với cookie
            if (accountLogin.cookie) {
                await this.puppeteerService.setRawCookies(accountLogin.cookie, '.facebook.com', page);
                const dataFbDtsgRev = await this.checkLogin(page, accountLogin);
                if (dataFbDtsgRev) {
                    return dataFbDtsgRev;
                }
            }
            // Login với tài khoản và mật khẩu
            if (accountLogin.userId && accountLogin.password) {
                await this.loginFacebookByPassword(page, accountLogin.userId, accountLogin.password);
                const currentUrl = page.url();
                if (currentUrl.includes('/authentication/')) {
                    throw new Error(`Tài khoản này cần giải captcha, bạn hãy vào trang quảng lý tài khoản, nhấn mở chrome để đăng nhập thủ công "${accountLogin.userId}"!`);
                }
                if (currentUrl.includes('/two_factor/')) {
                    if (!accountLogin.code2fa) {
                        throw new Error(`Tài khoản "${accountLogin.userId}" không có thông tin 2fa!`);
                    }
                    await this.inputCode2fa(page, accountLogin.code2fa);
                }
                const dataFbDtsgRev = await this.checkLogin(page, accountLogin);
                if (dataFbDtsgRev) {
                    return dataFbDtsgRev;
                }
            }
            this.puppeteerService.closePage(pageId);
            throw new Error(`Không thể đăng nhập tài khoản vui lòng kiểm tra lại thông tin đăng nhập và tài khoản "${accountLogin.userId}"!`);
        } catch (error) {
            this.puppeteerService.closePage(pageId);
            throw error;
        }
    }

    /** Xử lý đăng nhập fb với tài khoản mk 2fa */
    private async loginFacebookByPassword(page: Page, userId: string, password: string) {
        await this.puppeteerService.gotoUrl(page, 'https://www.facebook.com/?locale=en_EN');
        await page.waitForSelector('input[name="email"]');
        await page.type('input[name="email"]', userId);
        await page.type('input[name="pass"]', password);
        try {
            await page.click('button[name="login"]');
        } catch (error) {
            await page.click('div[aria-label="Log In"]');
        }
        await this.puppeteerService.waitForPageNavigation(page);
    }

    /** Xử lý nhập mã 2fa */
    private async inputCode2fa(page: Page, code2fa: string) {
        await this.puppeteerService.reloadPage(page);
        code2fa = code2fa.replace(/ /g, '');
        const token = await this.getCode2fa(code2fa);
        await page.keyboard.type(token);
        await Promise.all([
            this.puppeteerService.waitForPageNavigation(page),
            page.keyboard.press('Enter')
        ]);
        await this.puppeteerService.gotoUrl(page, 'https://www.facebook.com/?locale=en_EN');
    }

    private async saveNewCookieAccountFb(page: Page, account: Account) {
        try {
            const rawCookie = await this.puppeteerService.getRawCookies(page);
            account.cookie = rawCookie;
            await accountRepository.updateCookieAccount(account.id, rawCookie);
        } catch (error) {} // không cần xử lý lỗi ở đây bởi về lần sau chạy lại có thể cho đăng nhập lại
    }

    private async getFbInitData(page: Page): Promise<{ fbdtsg?: string, rev?: string }> {
        const html = await page.content();
        let fbdtsg = AppUtils.cutStringStartEnd(html, 'fb_dtsg" value="', '"');
        if (!fbdtsg) {
            fbdtsg = AppUtils.cutStringStartEnd(html, 'DTSGInitialData",[],{"token":"', '"');
        }
        const rev = AppUtils.cutStringStartEnd(html, 'client_revision":', ',');
        return { fbdtsg, rev };
    }

    private async handleGetFbInitData(page: Page, pageId: string) {
        const { fbdtsg, rev } = await this.getFbInitData(page);
        if (!fbdtsg || !rev) {
            this.puppeteerService.closePage(pageId);
            throw new Error('Không tìm thấy fb_dtsg hoặc rev');
        }
        return { fbdtsg, rev };
    }

    public async buildParamsFBDesktop(account: Account, page: Page, pageId: string) {
        if (!account.fbdtsg || !account.rev) {
            const { fbdtsg, rev } = await this.handleGetFbInitData(page, pageId);
            account.fbdtsg = fbdtsg;
            account.rev = rev;
        }
        return {
            'av': account.userId,
            '__user': account.userId,
            '__a': '1',
            '__dyn': "1KQdAmm1gxu4U4ifGh28sBBgS5UqxKcwRwAxu3-UcodUbE6u7HzE24xm6Uhx61rxicwcW4o29wmU1a852q3q5U2nwvE6W786q5Esx26UhwWwnElzaw5KzHzoaUae1AwgE5y6E52229wcq1FwKCwyxe",
            '__csr': '',
            '__req': AppUtils.makeid(2),
            '__beoa': '0',
            '__pc': 'EXP2:comet_pkg',
            'dpr': '1',
            '__ccg': 'EXCELLENT',
            '__rev': account.rev,
            '__s': AppUtils.makeid(6) + ':' + AppUtils.makeid(6) + ':' + AppUtils.makeid(6),
            '__hsi': '6' + AppUtils.makeNumber(19) + '-0',
            '__comet_req': '0',
            'fb_dtsg': account.fbdtsg,
            'jazoest': AppUtils.getNumericValue(account.fbdtsg),
            '__spin_r': account.rev,
            '__spin_b': 'trunk',
            '__spin_t': AppUtils.getSpinT(),
            'server_timestamps': true,
        }
    }

    public async evaluateScriptFbXMLHttpRequest(pageId: string, account: Account, options: IOptionsXMLHttpRequest) {
        const page = this.puppeteerService.getPage(pageId);
        if (typeof options.data === 'object' && (!account.fbdtsg || !account.rev)) {
            options.data = AppUtils.buildQueryString({
                ...this.buildParamsFBDesktop(account, page, pageId),
                ...options.data
            });
        }
        return await this.puppeteerService.evaluateScriptXMLHttpRequest(pageId, options);
    }

    /** Tự động lướt trang */
    public async autoScrollPage(pageId: string, timeScroll: number, options: IOptionsAutoScrollPage) {
        const page = this.puppeteerService.getPage(pageId);
        const startTime = Date.now();

        while (Date.now() - startTime < timeScroll) {
        const chunkTime = 30000; // chạy 30s mỗi đợt
        await page.evaluate(
            async ({ chunkTime, delayFrom, delayTo, scrollStepFrom, scrollStepTo }) => {
            const start = performance.now();
            while (performance.now() - start < chunkTime) {
                const scrollStep = Math.floor(Math.random() * (scrollStepTo - scrollStepFrom + 1)) + scrollStepFrom;
                window.scrollBy(0, scrollStep);
                await new Promise(resolve =>
                    setTimeout(resolve, Math.floor(Math.random() * (delayTo - delayFrom + 1)) + delayFrom)
                );
            }
            },
            { chunkTime, ...options }
        );
        }

        return Date.now() - startTime;
    }
}

export const FacebookPuppeteer = new _FacebookPuppeteer(PuppeteerService);

export function facebookPuppeteerHandlers(win: BrowserWindow) {
    ipcMain.handle('facebookPuppeteer:openChromeByAccount', async (event: IpcMainInvokeEvent, account: Account) => {
        return FacebookPuppeteer.openChromeByAccount(account);
    });
    ipcMain.handle('facebookPuppeteer:closeChromeByAccount', async (event: IpcMainInvokeEvent, account: Account) => {
        return FacebookPuppeteer.closeChromeByAccount(account);
    });
    ipcMain.handle('facebookPuppeteer:createPageFacebook', async (event: IpcMainInvokeEvent, account: Account, channelTemporary: string | undefined) => {
        return FacebookPuppeteer.createPageFacebook(account, (pageId) => {
            if (channelTemporary) {
                event.sender.send(channelTemporary, pageId);
            }
        });
    });
    ipcMain.handle('facebookPuppeteer:evaluateScriptFbXMLHttpRequest', async (event: IpcMainInvokeEvent, pageId: string, account: Account, options: IOptionsXMLHttpRequest) => {
        return FacebookPuppeteer.evaluateScriptFbXMLHttpRequest(pageId, account, options);
    });
    ipcMain.handle('facebookPuppeteer:autoScrollPage', async (event: IpcMainInvokeEvent, pageId: string, timeScroll: number, options: IOptionsAutoScrollPage) => {
        return FacebookPuppeteer.autoScrollPage(pageId, timeScroll, options);
    });
}
