import { AppDataSource } from "../typeorm.config";
import { ipcMain, IpcMainInvokeEvent } from "electron";
import { FileIdEntity } from "../entities/fileId.entity";
import { In } from "typeorm";
import { FileId, TypeFileId } from "src/models/FileId";

class FileIdRepository {
    private getRepoEntities() {
        return AppDataSource.getRepository(FileIdEntity);
    }
    public async getAll() {
        const fileIdRepo = this.getRepoEntities();
        return await fileIdRepo.find({ relations: { category: true } });
    }
    public async getAllByType(type: TypeFileId) {
        const fileIdRepo = this.getRepoEntities();
        return await fileIdRepo.find({
            where: { type: type },
            relations: ["category"],
        });
    }
    public async getFileIdByIds(ids: number[]) {
        const fileIdRepo = this.getRepoEntities();
        return await fileIdRepo.find({
            where: { id: In(ids) },
            relations: ["category"],
        });
    }
    public async addFileId(fileId: FileId) {
        const fileIdRepo = this.getRepoEntities();
        const fileIdEntity = fileIdRepo.create({
            name: fileId.name,
            textIds: fileId.listId.join('\n'),
            type: fileId.type,
            category: fileId.category?.id ? { id: fileId.category.id } : null,
        });
        const savedFileIdEntity = await fileIdRepo.save(fileIdEntity);
        return await this.getFileIdById(savedFileIdEntity.id);
    }
    public async updateCategoryFileIdByIds(ids: number[], categoryId?: number) {
        const fileIdRepo = this.getRepoEntities();
        return await fileIdRepo.update(ids, {
            category: categoryId ? { id: categoryId } : null,
        });
    }
    public async updateFileId(fileId: FileId) {
        const fileIdRepo = this.getRepoEntities();
        return await fileIdRepo.update(fileId.id, {
            name: fileId.name,
            textIds: fileId.listId.join('\n'),
            type: fileId.type,
            category: fileId.category?.id ? { id: fileId.category.id } : null,
        });
    }
    public async getFileIdById(id: number) {
        const fileIdRepo = this.getRepoEntities();
        return await fileIdRepo.findOne({
            where: { id: id },
            relations: ["category"],
        });
    }
    public async deleteFileIdByIds(ids: number[]) {
        const fileIdRepo = this.getRepoEntities();
        return await fileIdRepo.delete(ids);
    }
}
const fileIdRepository = new FileIdRepository();

export function fileIdRepositoryHandlers(win: Electron.BrowserWindow) {
    ipcMain.handle('database:fileId:getAll', async (event: IpcMainInvokeEvent) => {
        return fileIdRepository.getAll();
    });
    ipcMain.handle('database:fileId:getAllByType', async (event: IpcMainInvokeEvent, type: TypeFileId) => {
        return fileIdRepository.getAllByType(type);
    });
    ipcMain.handle('database:fileId:getFileIdByIds', async (event: IpcMainInvokeEvent, ids: number[]) => {
        return fileIdRepository.getFileIdByIds(ids);
    });
    ipcMain.handle('database:fileId:addFileId', async (event: IpcMainInvokeEvent, fileId: FileId) => {
        return fileIdRepository.addFileId(fileId);
    });
    ipcMain.handle('database:fileId:deleteFileIdByIds', async (event: IpcMainInvokeEvent, ids: number[]) => {
        return fileIdRepository.deleteFileIdByIds(ids);
    });
    ipcMain.handle('database:fileId:updateCategoryFileIdByIds', async (event: IpcMainInvokeEvent, ids: number[], categoryId: number) => {
        return fileIdRepository.updateCategoryFileIdByIds(ids, categoryId);
    });
    ipcMain.handle('database:fileId:updateFileId', async (event: IpcMainInvokeEvent, fileId: FileId) => {
        return fileIdRepository.updateFileId(fileId);
    });
}

export default fileIdRepository;
