import { ipcMain, IpcMainInvokeEvent, app, clipboard, session, BrowserWindow } from 'electron';
const { machineIdSync } = require('node-machine-id');
import * as dns from "dns";
import { exec, spawn } from 'child_process';
import os from 'os';
const winreg = require("winreg");
const asar = require("asar");
import * as path from 'node:path';
import { downloadFile } from './requestHandlers';
import AppUtils from '../utils';

class AppHandlerService {
    public platform = process.platform;

    public machineIdSync() {
        return machineIdSync();
    }

    public lookup(url: string) {
        return new Promise((resolve, reject) => {
            dns.lookup(url, (err, address, family) => {
                if (err) {
                    reject(err);
                } else {
                    resolve(address);
                }
            });
        });
    }

    public executeCommand(command: string): Promise<string> {
        return new Promise((resolve, reject) => {
            exec(command, (error, stdout, stderr) => {
                if (error) {
                    reject(`Error: ${error.message}`);
                    return;
                }
                resolve(stdout);
            });
        });
    }

    public async getRegistryValue(key: string, valueName: string): Promise<string> {
        return new Promise((resolve, reject) => {
            const regKey = new winreg({
                hive: winreg.HKCU,
                key: key
            });
            regKey.get(valueName, (error: Error, result: any) => {
                if (error) {
                    resolve('');
                    return;
                }
                resolve(result.value || '');
            })
        });
    }
    public async setRegistryValue(key: string, valueName: string, value: any) {
        return new Promise((resolve, reject) => {
            const regKey = new winreg({
                hive: winreg.HKCU,
                key: key
            });
            regKey.set(valueName, winreg.REG_SZ, value, (error: Error) => {
                if (error) {
                    reject(error);
                    return;
                }
                resolve(undefined);
            })
        });
    }

    public async extractAllAsar(pathAsar: string, extractedPath: string): Promise<void> {
        return asar.extractAll(pathAsar, extractedPath);
    }

    public async createPackageAsar(extractedPath: string, newPathAsar: string): Promise<void> {
        return await asar.createPackage(extractedPath, newPathAsar);
    }

    /** Khởi động lại app */
    public restartApp() {
        BrowserWindow.getAllWindows().forEach(window => window.close());
        app.relaunch();
        app.exit(0);
    }

    /** Xử lý kiểm tra version và cập nhật file main */
    public async updateMainApp() {
        const asarPath = process.env.APP_ROOT; // đường dân file app.asar
        const folderAppRoot = path.dirname(asarPath);
        const pathCurrentMain = path.join(folderAppRoot, "app.asar.unpacked", "dist-electron", "main.js");
        // Tải file main mới từ server về thay thế currentMain
        const urlMain = `${AppUtils.Url_Folder_App_Name}/download/main.js`;
        await downloadFile({ url: urlMain, method: "GET" }, pathCurrentMain, (percent: number) => {});
    }
}

export const appHandlerService = new AppHandlerService();

export function appHandlers(win: Electron.BrowserWindow) {

    ipcMain.handle('app:updateMainApp', async (event: IpcMainInvokeEvent) => {
        return appHandlerService.updateMainApp();
    });

    ipcMain.handle('app:restartApp', async (event: IpcMainInvokeEvent) => {
        return appHandlerService.restartApp();
    });

    ipcMain.handle('asar:extractAllAsar', async (event: IpcMainInvokeEvent, pathAsar: string, extractedPath: string) => {
        return appHandlerService.extractAllAsar(pathAsar, extractedPath);
    });

    ipcMain.handle('asar:createPackageAsar', async (event: IpcMainInvokeEvent, extractedPath: string, newPathAsar: string) => {
        return appHandlerService.createPackageAsar(extractedPath, newPathAsar);
    });

    ipcMain.handle('process:platform', async (event: IpcMainInvokeEvent) => {
        return appHandlerService.platform;
    });

    ipcMain.handle('pkg:machineIdSync', async (event: IpcMainInvokeEvent) => {
        const hwid = appHandlerService.machineIdSync();
        return hwid;
    });

    ipcMain.handle('dns:lookup', async (event: IpcMainInvokeEvent, url: string) => {
        return appHandlerService.lookup(url);
    });

    ipcMain.handle('close-app', () => {
        app.quit();
    });

    ipcMain.handle('app:get-version-app', () => {
        return app.getVersion();
    });

    /** Đọc văn bản từ clipboard */
    ipcMain.handle('electron:clipboard:readText', () => {
        return clipboard.readText();
    });
    /** Đọc hình ảnh từ clipboard */
    ipcMain.handle('electron:clipboard:readImage', () => {
        return clipboard.readImage();
    });
    /** Ghi văn bản vào clipboard */
    ipcMain.handle('electron:clipboard:writeText', (event: IpcMainInvokeEvent, text: string) => {
        return clipboard.writeText(text);
    });

    ipcMain.handle('app:Buffer', (event: IpcMainInvokeEvent, data: any, encoding: BufferEncoding = 'base64') => {
        return Buffer.from(data, encoding);
    });

    ipcMain.handle('app:child_process:executeCommand', (event: IpcMainInvokeEvent, cmd: string) => {
        return appHandlerService.executeCommand(cmd);
    });

    ipcMain.handle('app:winreg:getRegistryValue', (event: IpcMainInvokeEvent, key: string, valueName: string) => {
        return appHandlerService.getRegistryValue(key, valueName);
    });

    ipcMain.handle('app:winreg:setRegistryValue', (event: IpcMainInvokeEvent, key: string, valueName: string, value: any) => {
        return appHandlerService.setRegistryValue(key, valueName, value);
    });

    ipcMain.handle('app:clear-cache-and-exit', async (event) => {
        await session.defaultSession.clearCache();
        app.quit();
    });

    ipcMain.handle('app:app-path', async (event) => {
        const asarPath = process.env.APP_ROOT;
        return path.dirname(asarPath);
    });

    ipcMain.handle('app:app-product-mode', async (event) => {
        const isRunProductMode = AppUtils.runProductMode();
        return isRunProductMode;
    });

    ipcMain.handle('app:hostname', async (event) => {
        return os.hostname();
    });
}
