import { ipcMain, BrowserWindow, dialog, OpenDialogOptions, MessageBoxSyncOptions, SaveDialogSyncOptions } from 'electron';

export function dialogHandlers(window: BrowserWindow) {
    /** Mở hộp thoại chọn file */
    ipcMain.handle('showOpenDialogSync', async (event, options: OpenDialogOptions) => {
        const result: string[] | undefined = dialog.showOpenDialogSync(window, options);
        return result;
    });

    // Hiển thị Box hộp thoại
    ipcMain.handle('showMessageBoxSync', async (event, options: MessageBoxSyncOptions) => {
        const result = dialog.showMessageBoxSync(window, options);
        return result;
    });

    ipcMain.handle('showSaveDialogSync', async (event, options: SaveDialogSyncOptions) => {
        const result = dialog.showSaveDialogSync(window, options);
        return result;
    });
}