import { AppDataSource } from "../typeorm.config";
import { ipcMain, IpcMainInvokeEvent } from "electron";
import { Proxy } from "src/models/Proxy";
import { ProxyEntity } from "../entities/proxy.entity";
import { TypeLive, TypeProxy } from "src/models/App.model";

class ProxyRepository {
    private getRepoEntities() {
        return AppDataSource.getRepository(ProxyEntity);
    }
    public async getAll() {
        const proxyRepo = this.getRepoEntities();
        return await proxyRepo.find();
    }
    public async getProxyByIpAndPort(ip: string, port: string) {
        const proxyRepo = this.getRepoEntities();
        return await proxyRepo.findOne({ where: { ip: ip, port: port } });
    }
    public async getProxyByAccountId(accountId: number) {
        const proxyRepo = this.getRepoEntities();
        return await proxyRepo.findOne({ where: { accounts: { id: accountId } } });
    }
    public async addProxy(proxy: Proxy) {
        const proxyRepo = this.getRepoEntities();
        const proxyEntity = proxyRepo.create({
            ip: proxy.ip,
            port: proxy.port,
            type: proxy.type,
            username: proxy.username,
            password: proxy.password,
            live: proxy.live,
        });
        return await proxyRepo.save(proxyEntity);
    }
    public async updateLiveById(id: number, live: TypeLive) {
        const proxyRepo = this.getRepoEntities();
        return await proxyRepo.update(id, {
            live: live
        })
    }
    public async updateTypeProxyById(id: number, type: TypeProxy) {
        const proxyRepo = this.getRepoEntities();
        return await proxyRepo.update(id, {
            type: type
        })
    }
    public async deleteProxyByIds(ids: number[]) {
        const proxyRepo = this.getRepoEntities();
        return await proxyRepo.delete(ids);
    }
}

export const proxyRepository = new ProxyRepository();

export function proxyRepositoryHandlers(win: Electron.BrowserWindow) {
    ipcMain.handle('database:proxy:getAll', async (event: IpcMainInvokeEvent) => {
        return proxyRepository.getAll();
    });
    ipcMain.handle('database:proxy:getProxyByIpAndPort', async (event: IpcMainInvokeEvent, ip: string, port: string) => {
        return proxyRepository.getProxyByIpAndPort(ip, port);
    });
    ipcMain.handle('database:proxy:getProxyByAccountId', async (event: IpcMainInvokeEvent, accountId: number) => {
        return proxyRepository.getProxyByAccountId(accountId);
    });
    ipcMain.handle('database:proxy:addProxy', async (event: IpcMainInvokeEvent, proxy: Proxy) => {
        return proxyRepository.addProxy(proxy);
    });
    ipcMain.handle('database:proxy:updateLiveById', async (event: IpcMainInvokeEvent, id: number, live: TypeLive) => {
        return proxyRepository.updateLiveById(id, live);
    });
    ipcMain.handle('database:proxy:updateTypeProxyById', async (event: IpcMainInvokeEvent, id: number, type: TypeProxy) => {
        return proxyRepository.updateTypeProxyById(id, type);
    });
    ipcMain.handle('database:proxy:deleteProxyByIds', async (event: IpcMainInvokeEvent, ids: number[]) => {
        return proxyRepository.deleteProxyByIds(ids);
    });
}

export default proxyRepository;
