import { app } from 'electron'
import * as path from 'node:path'
import * as fs from "node:fs";
import os from "node:os";

class AppCoreUtils {
    public readonly Domain_App = "https://crm.alosoft.vn";
    public readonly Folder_App_Name = "SimpleFacebookProV2_10_02_2025";
    public readonly Url_Folder_App_Name = `${this.Domain_App}/${this.Folder_App_Name}`;
    public readonly Database_Name = "SimpleFbProV2_1758254293686.sqlite";
    public readonly Path_Database = path.join(app.getPath('userData'), this.Database_Name);
    public UrlApp = `${this.Url_Folder_App_Name}/index.html`;

    private folderLog: string = 'FolderLog';

    public getStartOfToday() {
        const now = new Date();
        return new Date(now.getFullYear(), now.getMonth(), now.getDate());
    };

    public formatDate(date = new Date()) {
        const day = String(date.getDate()).padStart(2, '0'); // Lấy ngày và đảm bảo 2 chữ số
        const month = String(date.getMonth() + 1).padStart(2, '0'); // Lấy tháng (tháng bắt đầu từ 0)
        const year = date.getFullYear(); // Lấy năm
        return `${day}-${month}-${year}`; // Ghép chuỗi theo định dạng "ngày-tháng-năm"
    };

    public getFormattedDateTime(now = new Date()) {
        const day = String(now.getDate()).padStart(2, '0');
        const month = String(now.getMonth() + 1).padStart(2, '0');
        const year = now.getFullYear();
        const hours = String(now.getHours()).padStart(2, '0');
        const minutes = String(now.getMinutes()).padStart(2, '0');
        return `${day}-${month}-${year} ${hours}:${minutes}`;
    };

    public logDebugging(...arg: string[]) {
        const folderLog = path.join(app.getPath('userData'), "Roaming", "SimpleFBPro", this.folderLog);
        if (!fs.existsSync(folderLog)) {
            fs.mkdirSync(folderLog, { recursive: true });
        }
        const startOfToday = this.getStartOfToday();
        const dateSting = this.formatDate(startOfToday).replaceAll('-', '_');
        const timeLog = this.getFormattedDateTime();
        const fileLog = path.join(folderLog, `${dateSting}.txt`);
        fs.appendFileSync(fileLog, `${timeLog}. ${arg.join(', ')}\n`, 'utf8');
    }

    public runProductMode(): boolean {
        const args = process.argv.slice(1);
        return !args.some(val => val === '--serve');
    }

    public cutStringStartEnd(original: string, startString: string, endString: string) {
        let result = original.split(startString);
        if (!result[1]) return '';
        if (!result[1].includes(endString)) return '';
        return result[1].split(endString)[0];
    }

    /** Để chạy 1 tác vụ promise mà không throw lỗi */
    public async handleTaskData<T>(callback: () => Promise<T>) {
        try {
            return await callback();
        } catch (error) {
            return undefined;
        }
    }

    public async getSystemChromePath(): Promise<string> {
        const platform = process.platform;
        let pathsChrome: string[] = [];
        if (platform === 'darwin') {
            pathsChrome = [
                '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
                path.join(os.homedir(), 'Applications/Google Chrome.app/Contents/MacOS/Google Chrome')
            ];
        }
        if (platform === 'win32') {
            const localAppData = (process as any).env.LOCALAPPDATA;
            const programFiles = (process as any).env.PROGRAMFILES;
            const programFilesX86 = (process as any).env["PROGRAMFILES(X86)"];
            pathsChrome = [
                'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe',
                'C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe',
                path.join(programFiles || "", "Google/Chrome/Application/chrome.exe"),
                path.join(programFilesX86 || "", "Google/Chrome/Application/chrome.exe"),
                path.join(localAppData || "", "Google/Chrome/Application/chrome.exe"),
            ];
        }
        if (platform === 'linux') {
            pathsChrome = [
                '/usr/bin/google-chrome',
                '/usr/local/bin/google-chrome',
                '/opt/google/chrome/chrome'
            ];
        }
        let pathChrome: string | undefined;
        for (const p of pathsChrome) {
            if (fs.existsSync(p)) {
                pathChrome = p;
                break;
            }
        }
        if (!pathChrome) {
            throw new Error('Không tìm thấy file chrome');
        }
        return pathChrome;
    }

    public normalizeToBuffer(data: any): Buffer {
        // 1️⃣ Đã là Buffer
        if (Buffer.isBuffer(data)) {
            return data;
        }
        // 2️⃣ ArrayBuffer
        if (data instanceof ArrayBuffer) {
            return Buffer.from(data);
        }
        // 3️⃣ TypedArray (Uint8Array, Int8Array, ...)
        if (ArrayBuffer.isView(data)) {
            return Buffer.from(data.buffer);
        }
        // 4️⃣ String
        if (typeof data === 'string') {
            return Buffer.from(data, 'utf8');
        }
        throw new Error('Unsupported data type for writeFile');
    }

    public makeid(length: number): string {
        let result = '';
        const characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
        const charactersLength = characters.length;
        for (let i = 0; i < length; i++) {
            result += characters.charAt(Math.floor(Math.random() * charactersLength));
        }
        return result;
    }

    public makeNumber(length: number) {
        let result = '';
        let characters = '0123456789';
        let charactersLength = characters.length;
        for (let i = 0; i < length; i++) {
            result += characters.charAt(Math.floor(Math.random() * charactersLength));
        }
        return result;
    }

    public getSpinT() {
        return Math.round(new Date().getTime() / 1000);
    }

    public getNumericValue(a: string) {
        let c = 0;
        for (var d = 0; d < a.length; d++)
            c += a.charCodeAt(d);

        return '2' + c.toString();
    }

    public stringifyKeyValuePair([key, value]: any[]) {
        return `${key}=${encodeURIComponent(value)}`
    }
    public buildQueryString(params: any) {
        if (!params) return ''
        return Object.entries(params)
          .map(this.stringifyKeyValuePair)
          .join('&')
    }

    public randomNumber(min: number, max: number) {
        return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    public sleep(ms: number): Promise<void> {
        return new Promise(resolve => setTimeout(resolve, ms));
    }

    public select(m: string, fullMess: string) {
        let choices = m.split("|");
        let index = Math.floor(Math.random() * choices.length) + 0;
        fullMess = fullMess.replace('{' + m + '}', choices[index]);
        return fullMess;
    }

    public spinText(content: string): string {
        let messContent = '';
        if (content) {
            messContent = content;
            let messRandom = messContent;
            let regex = /\{([^{}]+)\}/gm;
            let m;
            while ((m = regex.exec(messContent)) !== null) {
                // This is necessary to avoid infinite loops with zero-width matches
                if (m.index === regex.lastIndex) {
                    regex.lastIndex++;
                }
                messRandom = this.select(m[1], messRandom);
            }
            messContent = messRandom;
        }
        return messContent;
    }
}
const AppUtils = new AppCoreUtils();
export default AppUtils;
