import { AI } from "src/models/AI";
import { AIEntity } from "../entities/ai.entity";
import { AppDataSource } from "../typeorm.config";
import { ipcMain, IpcMainInvokeEvent } from "electron";

class AIRepository {
    private getRepository() {
        return AppDataSource.getRepository(AIEntity);
    }

    public async getAll() {
        const aiRepo = this.getRepository();
        return await aiRepo.find();
    }

    public async getAIById(id: number) {
        const aiRepo = this.getRepository();
        return await aiRepo.findOneBy({ id });
    }

    public async addAI(ai: AI) {
        const aiRepo = this.getRepository();
        const aiEntity = aiRepo.create({
            type_ai: ai.typeAI,
            api_key: ai.apiKey,
            prompt: "", // tạm không sử dụng key này do sắp tới sẽ chuyển sang lưu prompt sang bảng khác đầy đủ thông tin hơn (name, type, prompt, ...)
        });
        return await aiRepo.save(aiEntity)
    }

    public async updateAI(ai: AI) {
        const aiRepo = this.getRepository();
        return await aiRepo.update(ai.id, {
            api_key: ai.apiKey,
        })
    }

    public async deleteAIByIds(ids: number[]) {
        const aiRepo = this.getRepository();
        return await aiRepo.delete(ids);
    }
}

const aiRepository = new AIRepository();

export function aiRepositoryHandlers(win: Electron.BrowserWindow) {
    ipcMain.handle('database:ai:getAll', async (event: IpcMainInvokeEvent) => {
        return aiRepository.getAll();
    });
    ipcMain.handle('database:ai:addAI', async (event: IpcMainInvokeEvent, ai: AI) => {
        return aiRepository.addAI(ai);
    });
    ipcMain.handle('database:ai:updateAI', async (event: IpcMainInvokeEvent, ai: AI) => {
        return aiRepository.updateAI(ai);
    });
    ipcMain.handle('database:ai:deleteAIByIds', async (event: IpcMainInvokeEvent, ids: number[]) => {
        return aiRepository.deleteAIByIds(ids);
    });
    ipcMain.handle('database:ai:getAIById', async (event: IpcMainInvokeEvent, id: number) => {
        return aiRepository.getAIById(id);
    });
}

export default aiRepository;
