import { ProxyEntity } from "electron/database/entities/proxy.entity";
import { TypeLive, TypeProxy } from "./App.model";

export class Proxy {
    public id: number;
    public ip: string;
    public port: string;
    public type: TypeProxy;
    public live?: TypeLive;
    public username?: string;
    public password?: string;
    public checked?: boolean;
    public createdAt: Date;
    public updatedAt: Date;

    public toString() {
        if (this.username || this.password) {
            return this.username + ":" + this.password + "@" + this.ip + ":" + this.port
        }
        return this.ip + ":" + this.port
    }

    public static parseProxyFromString(s: string): Proxy | undefined {
        let proxy = new Proxy();
        let inputs = s.split(':');
        if (inputs.length === 2) {
            proxy.ip = inputs[0];
            proxy.port = inputs[1];
        } else if (inputs.length === 3) {
            let [password] = inputs[1].split('@')[0].split(':');
            proxy.username = inputs[0];
            proxy.password = password;
            proxy.ip =  inputs[1].split('@')[1];
            proxy.port =  inputs[2];
        } else if (inputs.length === 4 ) {
            proxy.ip = inputs[0];
            proxy.port = inputs[1];
            proxy.username = inputs[2];
            proxy.password = inputs[3];
        } else {
            throw new Error('Định dạng không hợp lệ')
        }
        if (!proxy.port || !proxy.ip) {
            return;
        }
        return proxy;
    }

    public static toProxyUrl(proxy: Proxy) {
        if (proxy.username && proxy.password) {
            return `${proxy.type}://${proxy.username}:${proxy.password}@${proxy.ip}:${proxy.port}`;
        }
        return `${proxy.type}://${proxy.ip}:${proxy.port}`;
    }

    public static map(proxyEntity: ProxyEntity) {
        const proxy = new Proxy();
        proxy.id = proxyEntity.id;
        proxy.ip = proxyEntity.ip;
        proxy.port = proxyEntity.port;
        proxy.type = proxyEntity.type as TypeProxy;
        proxy.live = proxyEntity.live as TypeLive;
        proxy.username = proxyEntity.username;
        proxy.password = proxyEntity.password;
        proxy.createdAt = proxyEntity.created_at;
        proxy.updatedAt = proxyEntity.updated_at;
        return proxy;
    }
    public static mapList(proxiesEntity: ProxyEntity[]) {
        return proxiesEntity.map(val => Proxy.map(val));
    }
}
