import { UsedIdEntity } from "electron/database/entities/usedIds.entity";

export type TypeUsedId = 'ReplyComment';

export class UsedId {
    public id: number;
    public scopeKey: string;
    public fbid: string;
    public type: TypeUsedId;
    public userId: string;
    public createdAt!: Date;
    public updatedAt!: Date;

    public static map(usedIdEntity: UsedIdEntity) {
        const usedId = new UsedId();
        usedId.id = usedIdEntity.id;
        usedId.scopeKey = usedIdEntity.scope_key;
        usedId.fbid = usedIdEntity.fbid;
        usedId.type = usedIdEntity.type as TypeUsedId;
        usedId.userId = usedIdEntity.user_id;
        usedId.createdAt = usedIdEntity.created_at;
        usedId.updatedAt = usedIdEntity.updated_at;
        return usedId;
    }
    public static mapList(usedIdEntity: UsedIdEntity[]) {
        return usedIdEntity.map(val => UsedId.map(val));
    }
}
