import { AppDataSource } from "../typeorm.config";
import { ipcMain, IpcMainInvokeEvent } from "electron";
import { CategoryEntity } from "../entities/category.entity";

class CategoryRepository {
    private getRepoEntities() {
        return AppDataSource.getRepository(CategoryEntity);
    }
    public async getAll() {
        const categoryRepo = this.getRepoEntities();
        return await categoryRepo.find();
    }
    public async getAllByType(type: string) {
        const categoryRepo = this.getRepoEntities();
        return await categoryRepo.find({ where: { type: type } });
    }
    public async getCategoryByNameAndType(name: string, type: string) {
        const categoryRepo = this.getRepoEntities();
        return await categoryRepo.findOne({ where: { name: name, type: type } });
    }
    public async addCategory(name: string, type: string) {
        const categoryRepo = this.getRepoEntities();
        const categoryEntity = categoryRepo.create({
            name: name,
            type: type
        });
        return await categoryRepo.save(categoryEntity);
    }
    public async deleteCategoryByIds(ids: number[]) {
        const categoryRepo = this.getRepoEntities();
        return await categoryRepo.delete(ids);
    }
}
const categoryRepository = new CategoryRepository();

export function categoryRepositoryHandlers(win: Electron.BrowserWindow) {
    ipcMain.handle('database:category:getAll', async (event: IpcMainInvokeEvent) => {
        return categoryRepository.getAll();
    });
    ipcMain.handle('database:category:getAllByType', async (event: IpcMainInvokeEvent, type: string) => {
        return categoryRepository.getAllByType(type);
    });
    ipcMain.handle('database:category:addCategory', async (event: IpcMainInvokeEvent, name: string, type: string) => {
        return categoryRepository.addCategory(name, type);
    });
    ipcMain.handle('database:category:deleteCategoryByIds', async (event: IpcMainInvokeEvent, ids: number[]) => {
        return categoryRepository.deleteCategoryByIds(ids);
    });
    ipcMain.handle('database:category:getCategoryByNameAndType', async (event: IpcMainInvokeEvent, name: string, type: string) => {
        return categoryRepository.getCategoryByNameAndType(name, type);
    });
}

export default categoryRepository;
