import { app, ipcMain } from 'electron'
import { createRequire } from 'node:module'
import type {
    ProgressInfo,
    UpdateDownloadedEvent,
    UpdateInfo,
} from 'electron-updater'
import AppUtils from '../utils';

const require = createRequire(__dirname)  // Chỉ dùng trong CommonJS
const { autoUpdater } = require('electron-updater')

export function update(win: Electron.BrowserWindow) {
    // Khi đặt thành false, quá trình tải xuống bản cập nhật sẽ được kích hoạt thông qua API
    autoUpdater.autoDownload = false
    autoUpdater.disableWebInstaller = false
    autoUpdater.allowDowngrade = false

    autoUpdater.on('checking-for-update', function () { });

    ipcMain.handle('check-update-app', async () => {
        if (!app.isPackaged) {
            const isRunProductMode = AppUtils.runProductMode();
            if (!isRunProductMode) {
                return { update: false, version: app.getVersion(), newVersion: null };
            }
            throw new Error('Tính năng cập nhật chỉ khả dụng sau khi đóng gói.');
        }
        return new Promise((resolve, reject) => {
            const timer = setTimeout(() => {
                reject(new Error('Đã xảy ra lỗi khi kiểm tra cập nhật'));
            }, 50000);

            // Lắng nghe sự kiện khi có bản cập nhật mới
            autoUpdater.on('update-available', (info: UpdateInfo) => {
                clearTimeout(timer);
                resolve({ update: true, version: app.getVersion(), newVersion: info?.version });
            });

            // Lắng nghe sự kiện khi không có bản cập nhật mới
            autoUpdater.on('update-not-available', (info: UpdateInfo) => {
                clearTimeout(timer);
                resolve({ update: false, version: app.getVersion(), newVersion: info?.version });
            });

            // Lắng nghe sự kiện lỗi khi kiểm tra bản cập nhật
            autoUpdater.on('error', (error: any) => {
                clearTimeout(timer);
                console.error('Lỗi khi kiểm tra bản cập nhật:', error);
                reject(error); // Xử lý lỗi
            });

            // Bắt đầu kiểm tra bản cập nhật
            autoUpdater.checkForUpdates();
        })
    });

    // Start downloading and feedback on progress
    ipcMain.handle('start-download', (event: Electron.IpcMainInvokeEvent, channel: string) => {
        startDownload(
            (error, progressInfo) => {
                if (error) {
                    event.sender.send(channel, { error });
                } else {
                    event.sender.send(channel, { percent: progressInfo?.percent, progressInfo });
                }
            }, () => {
                event.sender.send(channel, { percent: 100 });
            }
        )
    })


    // Install now
    ipcMain.handle('quit-and-install', () => {
        autoUpdater.quitAndInstall(false, true)
    })
}

function startDownload(
    callback: (error: Error | null, info: ProgressInfo | null) => void,
    complete: (event: UpdateDownloadedEvent) => void,
) {
    autoUpdater.on('download-progress', (info: ProgressInfo) => callback(null, info))
    autoUpdater.on('error', (error: Error) => callback(error, null))
    autoUpdater.on('update-downloaded', complete)
    autoUpdater.downloadUpdate()
}
