import { Column, Entity, PrimaryGeneratedColumn } from "typeorm";

@Entity('published_posts')
export class PublishedPostEntity {
    @PrimaryGeneratedColumn()
    id!: number;

    @Column({ type: "varchar", length: 255, nullable: false })
    post_id!: string; // ID của bài viết trên Facebook

    @Column({ type: "text", nullable: true })
    content!: string; // Nội dung bài viết

    @Column({ type: "varchar", length: 100, nullable: true })
    post_type!: string; // 'text', 'image', 'video', 'mixed'

    @Column({ type: "varchar", length: 255, nullable: true })
    target_type!: string; // 'profile', 'page', 'group'

    @Column({ type: "varchar", length: 255, nullable: true })
    target_id!: string; // ID của profile/page/group đã đăng

    @Column({ type: "varchar", length: 255, nullable: false, default: "User" })
    type_account!: string; // loại tài khoản đã đăng bài (User, Fanpage)

    @Column({ type: "varchar", length: 255, nullable: true })
    user_id!: string; // ID của tài khoản đăng bài

    @Column({ type: "datetime", default: () => "CURRENT_TIMESTAMP" })
    created_at!: Date;

    @Column({ type: "datetime", default: () => "CURRENT_TIMESTAMP", onUpdate: "CURRENT_TIMESTAMP" })
    updated_at!: Date;
}
