import { BrowserWindow, ipcMain, IpcMainInvokeEvent } from "electron";
import { accountRepositoryHandlers } from "./repository/account.repository";
import { proxyRepositoryHandlers } from "./repository/proxy.repository";
import { categoryRepositoryHandlers } from "./repository/category.repository";
import { aiRepositoryHandlers } from "./repository/ai.repository";
import { postRepositoryHandlers } from "./repository/post.repository";
import { scriptRepositoryHandlers } from "./repository/script.repository";
import { scheduleRepositoryHandlers } from "./repository/schedule.repository";
import { historyTaskRepositoryHandlers } from "./repository/historyTask.repository";
import { accessListItemRepositoryHandlers } from "./repository/accessListItem.repository";
import { fileIdRepositoryHandlers } from "./repository/fileId.repository";
import { usedIdRepositoryHandlers } from "./repository/usedId.repository";
import { publishedPostRepositoryHandlers } from "./repository/publishedPost.repository";
import settingsHandlers from "./repository/setting.repository";
import { AppDataSource } from "./typeorm.config";
import AppUtils from "../utils";

export default function databaseHandlers(win: BrowserWindow) {
    accountRepositoryHandlers(win);
    proxyRepositoryHandlers(win);
    categoryRepositoryHandlers(win);
    aiRepositoryHandlers(win);
    postRepositoryHandlers(win);
    fileIdRepositoryHandlers(win);
    scriptRepositoryHandlers(win);
    scheduleRepositoryHandlers(win);
    historyTaskRepositoryHandlers(win);
    accessListItemRepositoryHandlers(win);
    usedIdRepositoryHandlers(win);
    publishedPostRepositoryHandlers(win);
    settingsHandlers();

    ipcMain.handle('database:database-name', async (event) => {
        return AppUtils.Database_Name;
    });
    ipcMain.handle('database:disconnect', async (event: IpcMainInvokeEvent,) => {
        if (AppDataSource && AppDataSource.isInitialized) {
            await AppDataSource.destroy();
        }
    });
    ipcMain.handle('database:reconnect', async (event: IpcMainInvokeEvent,) => {
        if (AppDataSource && AppDataSource.isInitialized) {
            await AppDataSource.destroy();
        }
        await AppDataSource.initialize();
    });
    ipcMain.handle('database:get-path-database', async (event: IpcMainInvokeEvent,) => {
        return AppUtils.Path_Database;
    });
}
