import { AppDataSource } from "../typeorm.config";
import { ipcMain, IpcMainInvokeEvent } from "electron";
import { ScriptEntity } from "../entities/script.entity";
import { Script } from "src/models/Script/Script";
import { AccountEntity } from "../entities/account.entity";
import { IsNull, Not } from "typeorm";

class ScriptRepository {
    private getRepoEntities() {
        return AppDataSource.getRepository(ScriptEntity);
    }
    public async getAll() {
        const scriptRepo = this.getRepoEntities();
        return await scriptRepo.find({ relations: { accounts: true } });
    }
    public async addScript(script: Script) {
        const scriptRepo = this.getRepoEntities();
        const scriptEntity = scriptRepo.create({
            name: script.name,
            delay_from: script.delayFrom,
            delay_to: script.delayTo,
            media: script.media,
        });
        const savedScriptEntity = await scriptRepo.save(scriptEntity);
        return await this.getScriptById(savedScriptEntity.id);
    }
    public async updateScript(id: number, script: Script) {
        const scriptRepo = this.getRepoEntities();
        return await scriptRepo.update(id, {
            name: script.name,
            delay_from: script.delayFrom,
            delay_to: script.delayTo,
            media: script.media,
        });
    }
    public async getScriptById(id: number) {
        const scriptRepo = this.getRepoEntities();
        return await scriptRepo.findOne({
            where: { id: id },
            relations: [ "accounts" ],
        });
    }
    public async deleteScriptByIds(ids: number[]) {
        const scriptRepo = this.getRepoEntities();
        return await scriptRepo.delete(ids);
    }

    public async updateScriptAccounts(scriptId: number, accountIds: number[]) {
        const scriptRepository = this.getRepoEntities();
        const accountRepository = AppDataSource.getRepository(AccountEntity);
        // Tìm script theo ID
        const script = await scriptRepository.findOne({ where: { id: scriptId }, relations: ["accounts"] });
        if (!script) {
            throw new Error("Script không tồn tại");
        }
        // Tìm danh sách tài khoản theo danh sách ID
        const accounts = await accountRepository.findByIds(accountIds);
        // Cập nhật danh sách tài khoản
        script.accounts = accounts;
        const savedScriptEntity = await scriptRepository.save(script);
        return await this.getScriptById(savedScriptEntity.id);
    }

    /** Lấy toàn bộ script có đường dẫn media là không null */
    public async getScriptByMedia(): Promise<ScriptEntity[]> {
        const scriptRepo = this.getRepoEntities();
        const scripts = await scriptRepo.find({
            where: { media: Not(IsNull()) },
        });
        return scripts;
    }

    /** Cập nhật đường dẫn media của script */
    public async updateMediaScript(id: number, media: string) {
        const scriptRepo = this.getRepoEntities();
        return await scriptRepo.update(id, { media: media });
    }
}
const scriptRepository = new ScriptRepository();

export function scriptRepositoryHandlers(win: Electron.BrowserWindow) {
    ipcMain.handle('database:script:getAll', async (event: IpcMainInvokeEvent) => {
        return scriptRepository.getAll();
    });
    ipcMain.handle('database:script:addScript', async (event: IpcMainInvokeEvent, script: Script) => {
        return scriptRepository.addScript(script);
    });
    ipcMain.handle('database:script:deleteScriptByIds', async (event: IpcMainInvokeEvent, ids: number[]) => {
        return scriptRepository.deleteScriptByIds(ids);
    });
    ipcMain.handle('database:script:getScriptById', async (event: IpcMainInvokeEvent, id: number) => {
        return scriptRepository.getScriptById(id);
    });
    ipcMain.handle('database:script:updateScript', async (event: IpcMainInvokeEvent, id: number, script: Script) => {
        return scriptRepository.updateScript(id, script);
    });
    ipcMain.handle('database:script:updateScriptAccounts', async (event: IpcMainInvokeEvent, scriptId: number, accountIds: number[]) => {
        return scriptRepository.updateScriptAccounts(scriptId, accountIds);
    });
    ipcMain.handle('database:script:getScriptByMedia', async (event: IpcMainInvokeEvent) => {
        return scriptRepository.getScriptByMedia();
    });
    ipcMain.handle('database:script:updateMediaScript', async (event: IpcMainInvokeEvent, id: number, media: string) => {
        return scriptRepository.updateMediaScript(id, media);
    });
}

export default scriptRepository;
