import { BrowserWindow } from 'electron';
import { appHandlers } from './appHandlers';
import { requestHandlers } from './requestHandlers';
import { fsHandlers } from './fsHandlers';
import { dialogHandlers } from './dialogHandlers';
import { update } from './update';
import { puppeteerHandlers } from './puppeteer/handler';

export default function handlers(win: BrowserWindow) {
    appHandlers(win);
    requestHandlers(win);
    fsHandlers(win);
    dialogHandlers(win);
    update(win);
    puppeteerHandlers(win);
}
