import { Account, TypeAccount } from "src/models/Account";
import { AccountEntity } from "../entities/account.entity";
import { AppDataSource } from "../typeorm.config";
import { ipcMain, IpcMainInvokeEvent } from "electron";
import { AccessListItemEntity } from "../entities/accessListItem.entity";
import { In } from "typeorm";

class AccountRepository {
    private getRepoEntities() {
        return AppDataSource.getRepository(AccountEntity);
    }
    public async getProfileByType(type: TypeAccount | 'All', isDistinct: boolean = false) {
        const userRepo = this.getRepoEntities();
        if (type === 'All') {
            return await userRepo.find({ relations: { proxy: true, category: true, accessListItem: true, user_owner: true } });
        }
        if (isDistinct) {
            return await this.getProfileByTypeDistinct(type);
        }
        return await userRepo.find({ where: { type_account: type }, relations: { proxy: true, category: true, accessListItem: true, user_owner: true } });
    }

    public async getProfileByTypeDistinct(type: TypeAccount) {
        return await this.getRepoEntities()
            .createQueryBuilder('user')
            .leftJoinAndSelect('user.proxy', 'proxy')
            .leftJoinAndSelect('user.category', 'category')
            .leftJoinAndSelect('user.accessListItem', 'accessListItem')
            .leftJoinAndSelect('user.user_owner', 'user_owner')
            .where('user.type_account = :type', { type })
            .groupBy('user.user_id') // 🔥 gom theo user_id
            .getMany()
        ;
    }

    public async getAccountById(id: number) {
        const userRepo = this.getRepoEntities();
        return await userRepo.findOne({
            where: { id: id },
            relations: ["proxy", "category"], // Load quan hệ proxy và category
        });
    }
    public async getAccountByUserId(userId: string) {
        const userRepo = this.getRepoEntities();
        return await userRepo.findOne({ where: { user_id: userId } });
    }
    public async addAccountLogin(account: Account) {
        const userRepo = this.getRepoEntities();
        const user = userRepo.create({
            user_id: account.userId,
            name: account.name,
            user_agent: account.userAgent,
            cookie: account.cookie,
            password: account.password,
            email: account.email,
            pass_email: account.passMail,
            code2fa: account.code2fa,
            live: account.live,
            proxy: account.proxy?.id ? { id: account.proxy.id } : null,
            category: account.category?.id ? { id: account.category.id } : null,
        });
        const savedUser = await userRepo.save(user);
        return await this.getAccountById(savedUser.id);
    }
    /** Sử dụng khi nhập dữ liệu từ v1 */
    public async insertFullInfoAccount(account: Account) {
        const accessListItem = [];
        if (account.blackList.length > 0) {
            accessListItem.push(...account.blackList.map(val => ({ id: val.id })));
        }
        if (account.whiteList.length > 0) {
            accessListItem.push(...account.whiteList.map(val => ({ id: val.id })));
        }
        const userRepo = this.getRepoEntities();
        const user = userRepo.create({
            name: account.name,
            password: account.password,
            cookie: account.cookie,
            code2fa: account.code2fa,
            email: account.email,
            pass_email: account.passMail,
            user_agent: account.userAgent,
            user_id: account.userId,
            username: account.username,
            path_profile: account.pathProfile,
            proxy: account.proxy?.id ? { id: account.proxy.id } : null,
            category: account.category?.id ? { id: account.category.id } : null,
            accessListItem: accessListItem,
        });
        const savedUser = await userRepo.save(user);
        return await this.getAccountById(savedUser.id);
    }
    public async updateInfoAccount(id: number, account: Account) {
        const userRepo = this.getRepoEntities();
        return await userRepo.update(id, {
            name: account.name,
            username: account.username,
            user_agent: account.userAgent,
            cookie: account.cookie,
            password: account.password,
            email: account.email,
            pass_email: account.passMail,
            code2fa: account.code2fa,
            live: account.live,
            proxy: account.proxy?.id ? { id: account.proxy.id } : null,
            category: account.category?.id ? { id: account.category.id } : null,
        });
    }
    public async updateCookieAccount(id: number, cookie: string) {
        const userRepo = this.getRepoEntities();
        return await userRepo.update(id, { cookie, live: 'Live' });
    }
    public async updateLiveAccount(id: number, live: string) {
        const userRepo = this.getRepoEntities();
        return await userRepo.update(id, { live });
    }
    public async deleteAccountByIds(ids: number[]) {
        const userRepo = this.getRepoEntities();
        return await userRepo.delete(ids);
    }

    public async updateProxyForAccounts(accountsId: number[], proxyId: number | null) {
        const userRepo = this.getRepoEntities();
        return await userRepo.update(accountsId, {
            proxy: proxyId ? { id: proxyId } : null,
        });
    }

    public async addAccessListItemsToAccount(accountId: number, accessListItemIds: number[]) {
        const accountRepo = this.getRepoEntities();
        const accessListRepo = AppDataSource.getRepository(AccessListItemEntity);
        // Lấy account theo ID
        const account = await accountRepo.findOne({
            where: { id: accountId },
            relations: ["accessListItem"], // Load quan hệ accessListItem
        });
        if (!account) {
            throw new Error(`Account with ID ${accountId} not found`);
        }
        // Lấy danh sách AccessListItemEntity theo ID
        const accessListItems = await accessListRepo.find({ where: { id: In(accessListItemIds) } });
        if (accessListItems.length === 0) {
            throw new Error(`No AccessListItem found with the provided IDs`);
        }
        // Lọc ra các accessListItem chưa có trong account
        const newAccessListItems = accessListItems.filter(
            (item) => !account.accessListItem.some((existingItem) => existingItem.id === item.id)
        );
        if (newAccessListItems.length > 0) {
            // Thêm các accessListItem mới vào danh sách
            account.accessListItem.push(...newAccessListItems);
            await accountRepo.save(account);
        }
        return account;
    }
    public async removeAccessListItemsFromAccount(accountId: number, accessListItemIds: number[]) {
        const accountRepo = this.getRepoEntities();
        // Lấy account theo ID và load quan hệ accessListItem
        const account = await accountRepo.findOne({
            where: { id: accountId },
            relations: ["accessListItem"],
        });
        if (!account) {
            throw new Error(`Account with ID ${accountId} not found`);
        }
        // Lọc ra danh sách accessListItem còn lại sau khi gỡ bỏ
        account.accessListItem = account.accessListItem.filter(
            (item) => !accessListItemIds.includes(item.id)
        );
        // Cập nhật lại account
        await accountRepo.save(account);
        return account;
    }

    public async getAccessListItemByAccount(accountId: number): Promise<AccessListItemEntity[]> {
        const accountRepo = this.getRepoEntities();
        const account = await accountRepo.findOne({
            where: { id: accountId },
            relations: ["accessListItem"],
        });
        if (!account) {
            throw new Error(`Account with ID ${accountId} not found`);
        }
        return account.accessListItem;
    }

    // Mới cho fanpage
    public async getFanpageById(id: number) {
        const userRepo = this.getRepoEntities();
        return await userRepo.findOne({
            where: { id: id },
            relations: ["user_owner"],
        });
    }

    public async getPageIdsByAccountId(id: number): Promise<string[]> {
        const accountRepo = this.getRepoEntities();
        const result = await accountRepo.find({
            where: {
                type_account: 'Fanpage',
                user_owner: { id: id },
            },
            select: ['user_id'],
        });
        return result.map(item => item.user_id);
    }

    public async updateOrCreateFanpage(account: Account, ownerId: number) {
        const accountRepo = this.getRepoEntities();
        const existingAccount = await accountRepo.findOne({
            where: {
                user_id: account.userId,
                type_account: 'Fanpage',
                user_owner: {
                    id: ownerId,
                }
            }
        });

        if (existingAccount) {
            // Nếu đã tồn tại, cập nhật thông tin
            await accountRepo.update(existingAccount.id, {
                name: account.name,
                delegate_page_id: account.delegatePageId,
            });

            return await this.getFanpageById(existingAccount.id);
        } else {
            // Nếu chưa tồn tại, tạo mới
            const fanpageAccountEntity = accountRepo.create({
                user_id: account.userId,
                delegate_page_id: account.delegatePageId,
                name: account.name,
                type_account: 'Fanpage',
                user_owner: {
                    id: ownerId,
                }
            });

            await accountRepo.save(fanpageAccountEntity);
            return await this.getFanpageById(fanpageAccountEntity.id);
        }
    }

    public async deleteByPageIdsAndAccountId(pageIds: string[], accountId: number) {
        const accountRepo = this.getRepoEntities();
        return await accountRepo.delete({
            user_id: In(pageIds),
            user_owner: {
                id: accountId,
            },
        });
    }

    public async getFanpageByAccountId(id: number) {
        const accountRepo = this.getRepoEntities();
        return await accountRepo.find({
            where: {
                user_owner: {
                    id: id,
                },
            },
            relations: ['user_owner']
        });
    }

    /** Xoá profile của tài khoản */
    public async deleteProfileAccount(id: number) {
        const accountRepo = this.getRepoEntities();
        return await accountRepo.update(id, { path_profile: '' });
    }

    public async updateCategoryAccountIdByIds(ids: number[], categoryId?: number) {
        const accountRepo = this.getRepoEntities();
        return await accountRepo.update(ids, {
            category: categoryId ? { id: categoryId } : null,
        });
    }

    public async getCookieById(id: number) {
        const accountRepo = this.getRepoEntities();
        return await accountRepo.findOne({
            where: { id: id },
            select: ['cookie'],
        });
    }
}
export const accountRepository = new AccountRepository();

