import { AppDataSource } from "../typeorm.config";
import { SettingEntity } from "../entities/setting.entity";
import { ipcMain, IpcMainInvokeEvent } from "electron";

export class _SettingRepository {
    private getRepoEntities() {
        return AppDataSource.getRepository(SettingEntity);
    }

    // 📌 Lấy thông tin một setting theo Id
    public async getSettingById(id: number) {
        return await this.getRepoEntities().findOneBy({ id });
    }

    // 📌 Lấy thông tin một setting theo key
    public async getSettingByKey(key: string) {
        return await this.getRepoEntities().findOneBy({ key });
    }

    // 📌 Lấy tất cả settings để hiển thị lên trang cài đặt
    public async getAllSettingsPage() {
        return await this.getRepoEntities().find({
            where: { is_hide_page_setting: false },
            order: { category: "ASC", key: "ASC" }
        });
    }

    // 📌 Thêm 1 setting mới
    public async addSetting(setting: any) {
        const settingEntity = this.getRepoEntities().create(setting);
        return await this.getRepoEntities().save(settingEntity);
    }

    // 📌 Xoá 1 setting theo key
    public async deleteSettingByKey(key: string) {
        const setting = await this.getRepoEntities().findOneBy({ key: key });
        if (!setting) throw new Error("Setting not found");
        return await this.getRepoEntities().delete(setting.id);
    }

    // 📌 Cập nhật giá trị setting
    public async updateSettingValue(value: string, id: number) {
        const setting = await this.getRepoEntities().findOneBy({ id });
        if (!setting) throw new Error("Setting not found");
        setting.value = value;
        return await this.getRepoEntities().save(setting);
    }

    // 📌 Cập nhật giá trị setting theo key
    public async updateSettingValueByKey(value: string, key: string) {
        const setting = await this.getRepoEntities().findOneBy({ key: key });
        if (!setting) throw new Error("Setting not found");
        setting.value = value;
        return await this.getRepoEntities().save(setting);
    }
}

export const settingRepository = new _SettingRepository();

export default function settingsHandlers() {
    ipcMain.handle('database:settings:getSettingByKey', async (event: IpcMainInvokeEvent, key: string) => {
        return settingRepository.getSettingByKey(key);
    });
    ipcMain.handle('database:settings:getAllSettingsPage', async (event: IpcMainInvokeEvent) => {
        return settingRepository.getAllSettingsPage();
    });
    ipcMain.handle('database:settings:updateSettingValue', async (event: IpcMainInvokeEvent, value: string, id: number) => {
        return settingRepository.updateSettingValue(value, id);
    });
    ipcMain.handle('database:settings:updateSettingValueByKey', async (event: IpcMainInvokeEvent, value: string, key: string) => {
        return settingRepository.updateSettingValueByKey(value, key);
    });
    ipcMain.handle('database:settings:addSetting', async (event: IpcMainInvokeEvent, setting: any) => {
        return settingRepository.addSetting(setting);
    });
    ipcMain.handle('database:settings:deleteSettingByKey', async (event: IpcMainInvokeEvent, key: string) => {
        return settingRepository.deleteSettingByKey(key);
    });
}
