import { AppDataSource } from "../typeorm.config";
import { ScheduleEntity } from "../entities/schedule.entity";
import { AccountEntity } from "../entities/account.entity";
import { In, IsNull, Not } from "typeorm";
import { ipcMain, IpcMainInvokeEvent } from "electron";
import { Schedule } from "src/models/Schedule";
import cron from 'node-cron';

class ScheduleRepository {
    public async interruptExpiredRunningSchedules() {
        const currentTime = new Date();
        try {
            const result = await scheduleRepository.updateScheduleStatusBeforeDate(currentTime, 'Running', 'Interrupted');
            console.log(`Đã cập nhật ${result} lịch trình Running thành Interrupted`);
        } catch (error) {
            console.error('Lỗi khi cập nhật lịch trình Running thành Interrupted', error);
        }
        try {
            const result2 = await scheduleRepository.updateScheduleStatusBeforeDate(currentTime, 'Pending', 'Missed');
            console.log(`Đã cập nhật ${result2} lịch trình Pending thành Missed`);
        } catch (error) {
            console.error('Lỗi khi cập nhật lịch trình Pending thành Missed', error);
        }
    }

    private getRepoEntities() {
        return AppDataSource.getRepository(ScheduleEntity);
    }

    // 📌 Lấy tất cả lịch trình
    public async getAll() {
        return await this.getRepoEntities().find({ relations: { accounts: true } });
    }

    // 📌 Lấy lịch trình theo ID
    public async getScheduleById(id: number) {
        return await this.getRepoEntities().findOne({
            where: { id },
            relations: ["accounts"],
        });
    }

    // 📌 Xóa lịch trình theo danh sách ID
    public async deleteScheduleByIds(ids: number[]) {
        return await this.getRepoEntities().delete(ids);
    }

    // 📌 Lấy lịch trình theo phút
    public async getSchedulesByMinute(date: Date) {
        const formattedTime = date.toISOString().slice(0, 16).replace("T", " "); // Chuyển về 'YYYY-MM-DD HH:MM'
        return await this.getRepoEntities()
            .createQueryBuilder("schedule")
            .where("strftime('%Y-%m-%d %H:%M', schedule.schedule_time) = :formattedTime", { formattedTime })
            .getMany();
    }

    // 📌 Lọc lịch trình theo schedule_type
    public async getSchedulesByType(scheduleType: string) {
        return await this.getRepoEntities().find({ where: { schedule_type: scheduleType } });
    }

    // 📌 Lọc lịch trình theo status
    public async getSchedulesByStatus(status: string) {
        return await this.getRepoEntities().find({ where: { status } });
    }

    // 📌 Lấy lịch trình có trạng thái 'Pending' theo phút
    public async getPendingSchedulesByMinute(date: Date) {
        const formattedTime = date.toISOString().slice(0, 16).replace("T", " "); // Chuyển về 'YYYY-MM-DD HH:MM'
        return await this.getRepoEntities()
            .createQueryBuilder("schedule")
            .where("strftime('%Y-%m-%d %H:%M', schedule.schedule_time) = :formattedTime", { formattedTime })
            .andWhere("schedule.status = :status", { status: 'Pending' })
            .leftJoinAndSelect("schedule.accounts", "accounts") // Bao gồm thông tin accounts
            .leftJoinAndSelect("accounts.user_owner", "user_owner") // Bao gồm thông tin user_owner của từng account
            .getMany();
    }

    // 📌 Cập nhật trạng thái lịch trình trước thời điểm nhất định
    public async updateScheduleStatusBeforeDate(beforeDate: Date, fromStatus: string, toStatus: string) {
        const result = await this.getRepoEntities()
            .createQueryBuilder()
            .update(ScheduleEntity)
            .set({
                status: toStatus,
                updated_at: new Date()
            })
            .where("status = :fromStatus", { fromStatus })
            .andWhere("schedule_time < :beforeDate", { beforeDate })
            .execute();

        return result.affected || 0; // Trả về số lượng bản ghi đã được cập nhật
    }

    // 📌 Cập nhật trạng thái theo id
    public async updateStatusById(id: number, status: string) {
        const scheduleRepo = this.getRepoEntities();
        const result = await scheduleRepo.update(id, { status });
        if (result.affected && result.affected <= 0) {
            throw new Error('Cập nhật lịch trình thất bại không tìm thấy id hoặc lỗi không xác định');
        }
        return await this.getScheduleById(id);
    }

    // 📌 Tạo mới lịch trình với danh sách ID tài khoản
    public async createSchedule(schedule: Schedule) {
        const repo = this.getRepoEntities();
        const accountRepo = AppDataSource.getRepository(AccountEntity);

        // Lấy danh sách tài khoản theo ID
        let accounts: AccountEntity[] = [];
        if (schedule.accounts && schedule.accounts.length > 0) {
            const accountIds = schedule.accounts.map(val => val.id);
            accounts = await accountRepo.findBy({ id: In(accountIds) });
        }

        // Tạo lịch trình mới
        const newSchedule = repo.create({
            schedule_type: schedule.scheduleType,
            media: schedule.media,
            status: schedule.status,
            schedule_time: schedule.scheduleTime,
            accounts,
            type_account: schedule.typeAccount,
        });

        return await repo.save(newSchedule);
    }

    // 📌 Cập nhật lịch trình
    public async updateSchedule(id: number, schedule: Schedule) {
        const scheduleRepo = this.getRepoEntities();
        return await scheduleRepo.update(id, {
            schedule_type: schedule.scheduleType,
            media: schedule.media,
            status: schedule.status,
            schedule_time: schedule.scheduleTime,
        });
    }

    // 📌 Cập nhật thời gian lịch trình
    public async updateScheduleTime(id: number, scheduleTime: Date) {
        const scheduleRepo = this.getRepoEntities();
        const result = await scheduleRepo.update(id, { schedule_time: scheduleTime, status: 'Pending' });
        if (result.affected && result.affected <= 0) {
            throw new Error('Cập nhật lịch trình thất bại không tìm thấy id hoặc lỗi không xác định');
        }
        return await this.getScheduleById(id);
    }

    // 📌 Cập nhật tài khoản lịch trình
    public async updateScheduleAccounts(scheduleId: number, accountIds: number[]) {
        const scheduleRepo = this.getRepoEntities();
        const accountRepo = AppDataSource.getRepository(AccountEntity);
        // Tìm schedule entity
        const schedule = await scheduleRepo.findOne({
            where: { id: scheduleId },
            relations: ["accounts"]
        });
        if (!schedule) {
            throw new Error(`Schedule với ID ${scheduleId} không tồn tại`);
        }
        // Lấy danh sách accounts mới
        const accounts = await accountRepo.findBy({ id: In(accountIds) });
        // Cập nhật mối quan hệ
        schedule.accounts = accounts;
        // Lưu thay đổi
        return await scheduleRepo.save(schedule);
    }

    /** Lấy toàn bộ lịch trình có đường dẫn media là không null */
    public async getScheduleByMedia(): Promise<ScheduleEntity[]> {
        const scheduleRepo = this.getRepoEntities();
        const schedules = await scheduleRepo.find({
            where: { media: Not(IsNull()) },
        });
        return schedules;
    }

    /** Cập nhật đường dẫn media của lịch trình */
    public async updateMediaSchedule(id: number, media: string) {
        const scheduleRepo = this.getRepoEntities();
        return await scheduleRepo.update(id, { media: media });
    }
}
export const scheduleRepository = new ScheduleRepository();

export function scheduleRepositoryHandlers(win: Electron.BrowserWindow) {
    cron.schedule('* * * * *', async () => {
        const currentTime = new Date();
        try {
            const pendingSchedules = await scheduleRepository.getPendingSchedulesByMinute(currentTime);
            win.webContents.send('schedule:pending:minute', pendingSchedules);
        } catch (error) {
            console.error('Lỗi khi lấy lịch trình Pending:', error);
        }
    });

    ipcMain.handle('database:schedule:getAll', async (event: IpcMainInvokeEvent) => {
        return scheduleRepository.getAll();
    });
    ipcMain.handle('database:schedule:getScheduleById', async (event: IpcMainInvokeEvent, id: number) => {
        return scheduleRepository.getScheduleById(id);
    });
    ipcMain.handle('database:schedule:deleteScheduleByIds', async (event: IpcMainInvokeEvent, ids: number[]) => {
        return scheduleRepository.deleteScheduleByIds(ids);
    });
    ipcMain.handle('database:schedule:getSchedulesByMinute', async (event: IpcMainInvokeEvent, date: Date) => {
        return scheduleRepository.getSchedulesByMinute(date);
    });
    ipcMain.handle('database:schedule:getSchedulesByType', async (event: IpcMainInvokeEvent, scheduleType: string) => {
        return scheduleRepository.getSchedulesByType(scheduleType);
    });
    ipcMain.handle('database:schedule:getSchedulesByStatus', async (event: IpcMainInvokeEvent, status: string) => {
        return scheduleRepository.getSchedulesByStatus(status);
    });
    ipcMain.handle('database:schedule:createSchedule', async (event: IpcMainInvokeEvent, schedule: Schedule) => {
        return scheduleRepository.createSchedule(schedule);
    });
    ipcMain.handle('database:schedule:updateStatusById', async (event: IpcMainInvokeEvent, id: number, status: string) => {
        return scheduleRepository.updateStatusById(id, status);
    });
    ipcMain.handle('database:schedule:updateSchedule', async (event: IpcMainInvokeEvent, id: number, schedule: Schedule) => {
        return scheduleRepository.updateSchedule(id, schedule);
    });
    ipcMain.handle('database:schedule:updateScheduleAccounts', async (event: IpcMainInvokeEvent, scheduleId: number, accountIds: number[]) => {
        return scheduleRepository.updateScheduleAccounts(scheduleId, accountIds);
    });
    ipcMain.handle('database:schedule:updateScheduleTime', async (event: IpcMainInvokeEvent, id: number, scheduleTime: Date) => {
        return scheduleRepository.updateScheduleTime(id, scheduleTime);
    });
    ipcMain.handle('database:schedule:getScheduleByMedia', async (event: IpcMainInvokeEvent) => {
        return scheduleRepository.getScheduleByMedia();
    });
    ipcMain.handle('database:schedule:updateMediaSchedule', async (event: IpcMainInvokeEvent, id: number, media: string) => {
        return scheduleRepository.updateMediaSchedule(id, media);
    });
}

export default scheduleRepository;

