import AppUtils from "../utils";
import { settingRepository } from "../database/repository/setting.repository";

export class AppCoreService {
    private debugLoggingCache: {
        lastUpdateTime: number;
        isEnabled: boolean
    } | undefined;

    constructor() {}

    public async logDebug(message: string) {
        const currentTime = Date.now();
        const cacheExpiryTime = 10 * 1000; // 10s
        // Nếu cache chưa có hoặc đã hết hạn => cập nhật lại
        if (
            !this.debugLoggingCache ||
            currentTime - this.debugLoggingCache.lastUpdateTime >= cacheExpiryTime
        ) {
            const debugSetting = await settingRepository.getSettingByKey("debug.enableLogging");

            this.debugLoggingCache = {
                isEnabled: debugSetting?.value === "true",
                lastUpdateTime: currentTime,
            };
        }

        // Chỉ log nếu enable
        if (this.debugLoggingCache.isEnabled) {
            AppUtils.logDebugging(message);
        }
    }
}


export const appCoreService = new AppCoreService();
