import { PublishedPost } from "src/models/PublishedPost";
import { PublishedPostEntity } from "../entities/publishedPost.entity";
import { AppDataSource } from "../typeorm.config";
import { ipcMain, IpcMainInvokeEvent } from "electron";

class PublishedPostRepository {
    private getRepoEntities() {
        return AppDataSource.getRepository(PublishedPostEntity);
    }

    public async getAll() {
        const publishedPostRepo = this.getRepoEntities();
        return await publishedPostRepo.find({
            order: { created_at: "DESC" }
        });
    }

    public async addPublishedPost(publishedPost: PublishedPost) {
        const publishedPostRepo = this.getRepoEntities();
        const savedPublishedPost = await publishedPostRepo.save({
            post_id: publishedPost.postId,
            content: publishedPost.content,
            post_type: publishedPost.postType,
            target_type: publishedPost.targetType,
            target_id: publishedPost.targetId,
            type_account: publishedPost.typeAccount,
            user_id: publishedPost.userId,
        });
        return await this.getPublishedPostById(savedPublishedPost.id);
    }

    public async deletePublishedPostByIds(ids: number[]) {
        const publishedPostRepo = this.getRepoEntities();
        return await publishedPostRepo.delete(ids);
    }

    public async getPublishedPostById(id: number) {
        const publishedPostRepo = this.getRepoEntities();
        return await publishedPostRepo.findOne({
            where: { id: id }
        });
    }

    /** Lấy bài viết đã đăng theo user_id */
    public async getPublishedPostsByUserId(userId: string) {
        const publishedPostRepo = this.getRepoEntities();
        return await publishedPostRepo.find({
            where: { user_id: userId },
            order: { created_at: "DESC" }
        });
    }

    /** Lấy thống kê số lượng bài viết đã đăng */
    public async getPublishedPostsStats() {
        const publishedPostRepo = this.getRepoEntities();
        const total = await publishedPostRepo.count();

        const byTypeAccount = await publishedPostRepo
            .createQueryBuilder("published_post")
            .select("published_post.type_account", "typeAccount")
            .addSelect("COUNT(*)", "count")
            .groupBy("published_post.type_account")
            .getRawMany();

        const byTargetType = await publishedPostRepo
            .createQueryBuilder("published_post")
            .select("published_post.target_type", "targetType")
            .addSelect("COUNT(*)", "count")
            .groupBy("published_post.target_type")
            .getRawMany();

        return {
            total,
            byTypeAccount,
            byTargetType
        };
    }
}

const publishedPostRepository = new PublishedPostRepository();

export function publishedPostRepositoryHandlers(win: Electron.BrowserWindow) {
    /**
     * Lấy tất cả bài viết đã đăng
     * @returns Promise<PublishedPostEntity[]> - Danh sách tất cả bài viết đã đăng, sắp xếp theo thời gian tạo giảm dần
     */
    ipcMain.handle('database:published-post:getAll', async (event: IpcMainInvokeEvent) => {
        return publishedPostRepository.getAll();
    });

    /**
     * Thêm bài viết đã đăng mới vào database
     * @param publishedPost - Thông tin bài viết đã đăng cần thêm
     * @returns Promise<PublishedPostEntity> - Bài viết đã đăng vừa được thêm (có đầy đủ thông tin)
     */
    ipcMain.handle('database:published-post:addPublishedPost', async (event: IpcMainInvokeEvent, publishedPost: PublishedPost) => {
        return publishedPostRepository.addPublishedPost(publishedPost);
    });

    /**
     * Xóa bài viết đã đăng theo danh sách ID
     * @param ids - Mảng ID của các bài viết cần xóa
     * @returns Promise<DeleteResult> - Kết quả xóa từ database
     */
    ipcMain.handle('database:published-post:deletePublishedPostByIds', async (event: IpcMainInvokeEvent, ids: number[]) => {
        return publishedPostRepository.deletePublishedPostByIds(ids);
    });

    /**
     * Lấy bài viết đã đăng theo ID cụ thể
     * @param id - ID của bài viết cần lấy
     * @returns Promise<PublishedPostEntity | null> - Bài viết đã đăng hoặc null nếu không tìm thấy
     */
    ipcMain.handle('database:published-post:getPublishedPostById', async (event: IpcMainInvokeEvent, id: number) => {
        return publishedPostRepository.getPublishedPostById(id);
    });

    /**
     * Lấy danh sách bài viết đã đăng theo user ID
     * @param userId - ID của user cần lấy bài viết
     * @returns Promise<PublishedPostEntity[]> - Danh sách bài viết đã đăng của user, sắp xếp theo thời gian tạo giảm dần
     */
    ipcMain.handle('database:published-post:getPublishedPostsByUserId', async (event: IpcMainInvokeEvent, userId: string) => {
        return publishedPostRepository.getPublishedPostsByUserId(userId);
    });

    /**
     * Lấy thống kê về bài viết đã đăng
     * @returns Promise<{total: number, byTypeAccount: any[], byTargetType: any[]}> - Thống kê tổng số bài viết và phân loại theo loại tài khoản và loại đích đến
     */
    ipcMain.handle('database:published-post:getPublishedPostsStats', async (event: IpcMainInvokeEvent) => {
        return publishedPostRepository.getPublishedPostsStats();
    });
}

export default publishedPostRepository;
