import { BrowserWindow, ipcMain, IpcMainInvokeEvent, screen } from "electron";
import puppeteer, { Browser, GoToOptions, HTTPResponse, LaunchOptions, Page } from "puppeteer";
import crypto from "crypto";
import { Proxy } from "src/models/Proxy";
import { settingRepository } from "../../database/repository/setting.repository";
import { appHandlerService } from "../appHandlers";
import path from "path";
import { fileHandler } from "../fsHandlers";
import AppUtils from "../../utils";

interface DataRecordNetworkData {
    url: string;
    method: string;
    contentType: string;
    status: number;
    requestData: any;
    responseBody: string | null;
    params: { [k: string]: string };
    time: string;
}
export class _PuppeteerService {
    public browserMap: Map<string, Browser> = new Map();
    public proxyMap: Map<string, Proxy> = new Map();
    public pageMap: Map<string, Page> = new Map();
    public pageIdInitMap: Map<string, boolean> = new Map();
    public defaultOptions: GoToOptions = { waitUntil: 'load', timeout: 120000 };

    public async resetPuppeteerService() {
        for (const browser of this.browserMap.values()) {
            try {
                await browser.close();
            } catch (err) {
                console.error('Lỗi đóng browser:', err);
            }
        }
        this.browserMap.clear();
        this.pageMap.clear();
        this.proxyMap.clear();
        this.pageIdInitMap.clear();
    }

    private queue: (() => Promise<void>)[] = []; // Hàng đợi các tác vụ tạo browser
    private isProcessing = false;                // Đánh dấu xem hàng đợi có đang xử lý không
    private delayMs: number = 10000;             // Thời gian delay giữa các tác vụ tạo browser 10s
    /**
     * Hàm này được gọi để tạo browser mới
     * Tuy nhiên thay vì thực thi ngay, nó sẽ đẩy vào hàng đợi và thực thi tuần tự, mỗi lần cách nhau 10s
     * @param options - Tùy chọn khởi tạo Puppeteer browser
     * @returns Promise trả về browser sau khi được khởi tạo
     */
    public async createBrowser(options: LaunchOptions, browserId: string, pageId: string, proxy?: Proxy): Promise<{ browser: Browser, page: Page }> {
        return new Promise<{ browser: Browser, page: Page }>((resolve, reject) => {
            // Đưa tác vụ tạo browser vào hàng đợi
            this.queue.push(async () => {
                try {
                    let browser = this.browserMap.get(browserId);
                    if (browser) {
                        // Nếu browser đã tồn tại thì tạo page mới (do người dùng thao tác chạy tác vụ mới cho tài khoản quá nhanh sẽ vào đây)
                        const { page } = await this.createPage(browserId, pageId);
                        this.setPage(pageId, page);
                        resolve({ browser, page });
                    } else {
                        const userDataDir = options.userDataDir;
                        if (userDataDir) {
                            // 1. Kiểm tra xem chrome đang mở ngầm hay không
                            const isAlive = await this.isChromeAlive(userDataDir);
                            if (isAlive) {
                                await this.killChrome(userDataDir);
                            }
                            const lockFile = path.join(userDataDir, 'SingletonLock');
                            if (fileHandler.existsSync(lockFile)) {
                                await fileHandler.unlink(lockFile);
                            }
                        }

                        browser = await puppeteer.launch(options); // tạo browser

                        // 🟡 Lắng nghe sự kiện browser bị tắt
                        browser.on('disconnected', () => {
                            this.browserMap.delete(browserId);
                            this.deletePageByBrowserId(browserId);
                        });
                        this.setBrowser(browserId, browser);
                        const page = (await browser.pages())[0];
                        if (proxy && proxy?.username && proxy?.password) {
                            await page.authenticate({
                                username: proxy.username,
                                password: proxy.password,
                            });
                        }
                        this.setPage(pageId, page);
                        if (proxy) {
                            this.proxyMap.set(browserId, proxy);
                        }
                        resolve({ browser, page }); // trả về browser cho bên gọi
                    }
                } catch (err) {
                    reject(err); // nếu lỗi thì trả về lỗi
                }
                // Sau khi tạo xong, chờ delay rồi mới xử lý tiếp tác vụ kế tiếp
                await new Promise((r) => setTimeout(r, this.delayMs));
                this.processQueue(); // tiếp tục xử lý hàng đợi
            });
            // Nếu chưa xử lý hàng đợi thì bắt đầu xử lý
            if (!this.isProcessing) {
                this.processQueue();
            }
        });
    }
    /**
     * Hàm nội bộ để xử lý lần lượt từng tác vụ trong hàng đợi
     */
    private async processQueue() {
        if (this.queue.length === 0) {
            this.isProcessing = false; // Không còn tác vụ nào thì đánh dấu là không còn xử lý
            return;
        }
        this.isProcessing = true;
        const job = this.queue.shift(); // lấy tác vụ đầu tiên trong hàng đợi
        if (job) await job(); // thực thi tác vụ
    }

    private async isChromeAlive(profilePath: string) {
        try {
            const normalizedProfile = path.resolve(profilePath).replace(/\\/g, '/').toLowerCase();
            const platform = process.platform;
            let cmd = '';
            if (platform === 'win32') {
                cmd = `wmic process where "name='chrome.exe'" get CommandLine /value`;
            } else if (platform === 'darwin' || platform === 'linux') {
                cmd = `ps -ef | grep -i chrome | grep -v grep`;
            }
            const output = await appHandlerService.executeCommand(cmd);
            const normalizedOutput = output.replace(/\\/g, '/').toLowerCase();
            const regex = new RegExp(`--user-data-dir[= ]"?${normalizedProfile}"?`, 'i');
            const isRunning = regex.test(normalizedOutput);
            return isRunning;
        } catch (error) {
            return false;
        }
    }
    private async killChrome(profilePath: string) {
        try {
            if (process.platform === 'win32') {
                await appHandlerService.executeCommand(`taskkill /F /IM chrome.exe /FI "WINDOWTITLE eq ${profilePath}"`);
            } else {
                await appHandlerService.executeCommand(`pkill -f "${profilePath}"`);
            }
        } catch (error) {
            console.error('Lỗi kill Chrome:', error);
        }
    }

    public async reloadSettings() {
        const setting = await settingRepository.getSettingByKey('puppeteer.delayMs');
        if (setting) {
            this.delayMs = parseInt(setting.value) || 20000;
        }
    }

    public async createPage(browserId: string, pageId: string) {
        const size = screen.getPrimaryDisplay().workAreaSize;
        let browser: Browser = this.getBrowser(browserId);
        const page = await browser.newPage();
        const proxy = this.proxyMap.get(browserId);
        if (proxy && proxy?.username && proxy?.password) {
            await page.authenticate({
                username: proxy.username,
                password: proxy.password,
            });
        }
        await page.setViewport({ width: size.width, height: size.height });
        this.setPage(pageId, page);
        return { page, proxy };
    }

    /** Tạo page id */
    public createPageId(browserId: string) {
        const id = crypto.randomBytes(16).toString('hex');
        return `${browserId}-${id}`;
    }
    /** Lấy browser id từ page id */
    public getBrowserIdFromPageId(pageId: string) {
        return pageId.split('-')[0];
    }
    /** Xoá toàn bộ page từ browserId */
    public deletePageByBrowserId(browserId: string) {
        this.pageMap.forEach((page, pageId) => {
            if (this.getBrowserIdFromPageId(pageId) === browserId) {
                this.pageMap.delete(pageId);
            }
        });
    }

    public setBrowser(browserId: string, browser: Browser) {
        this.browserMap.set(browserId, browser);
    }
    public setPage(pageId: string, page: Page) {
        this.pageMap.set(pageId, page);
        this.removePageIdInit(pageId);
    }

    public setInitPageId(pageId: string) {
        this.pageIdInitMap.set(pageId, true);
    }
    public removePageIdInit(pageId: string) {
        this.pageIdInitMap.delete(pageId);
    }


    public getBrowser(browserId: string) {
        const browser = this.browserMap.get(browserId);
        if (!browser) {
            throw new Error('Không tìm thấy browser ' + browserId);
        }
        return browser;
    }
    public getPage(pageId: string) {
        const page = this.pageMap.get(pageId);
        if (!page) {
            throw new Error('Không tìm thấy page ' + pageId);
        }
        return page;
    }

    /** Xoá page */
    public async closePage(pageId: string) {
        const page = this.getPage(pageId);
        await page.close();
        this.pageMap.delete(pageId);
        const browserId = this.getBrowserIdFromPageId(pageId);
        const browser = this.getBrowser(browserId);
        const pages = await browser.pages();
        if (pages.length === 0) {
            await browser.close();
            this.browserMap.delete(browserId);
        }
        await AppUtils.sleep(1000); // khi đóng page thì đợi 1 giây để đảm bảo page đã đóng
    }

    /** Thay thế page hiện tại bằng 1 page mới */
    public async replacePage(pageId: string) {
        const browserId = this.getBrowserIdFromPageId(pageId);
        const browser = this.getBrowser(browserId);
        const newPage = await browser.newPage();
        await this.closePage(pageId);
        this.pageMap.set(pageId, newPage);
        return newPage;
    }

    /** Tạo page mới từ pageId */
    public async createPageFromPageId(pageId: string) {
        const browserId = this.getBrowserIdFromPageId(pageId);
        const browser = this.getBrowser(browserId);
        const newPage = await browser.newPage();
        return newPage;
    }

    /** Chụp ảnh màn hình */
    public async captureScreenshot(pageId: string) {
        const isInit = this.pageIdInitMap.has(pageId);
        if (isInit) {
            return;
        }
        const page = this.getPage(pageId);
        return await page.screenshot({ encoding: 'base64' });
    }

    /** Set cookie */
    public async setRawCookies(rawCookie: string, domain: string, page: Page) {
        // Parse cookie chuỗi thành mảng cookie object
        const cookieList: any = rawCookie
            .split(';')
            .map(cookieStr => {
                const [rawName, ...rawValueParts] = cookieStr.trim().split('=');
                const name = rawName.trim();
                const value = rawValueParts.join('=').trim();

                if (!name || !value) return null;

                return {
                    name,
                    value,
                    domain: domain,
                    path: '/',
                };
            })
            .filter((c) => !!c); // Lọc bỏ null

        // Set cookies vào trình duyệt
        await page.setCookie(...cookieList);
    };

    public async getRawCookies(page: Page) {
        const cookies = await page.cookies();
        const rawCookie = cookies.map((c: any) => `${c.name}=${c.value}`).join('; ');
        return rawCookie;
    }

    public async clearInput(page: Page, selector: string) {
        await page.click(selector);
        // await page.keyboard.down('Control');
        const isMac = process.platform === 'darwin';
        await page.keyboard.down(isMac ? 'Meta' : 'Control');
        await page.keyboard.press('A');
        await page.keyboard.up(isMac ? 'Meta' : 'Control');
        await page.keyboard.press('Backspace');
    }

    public async evaluateScriptXMLHttpRequest(
        page: string | Page,
        {
            url,
            method = 'GET',
            headers = {},
            data = null,
            withCredentials = false
        }: IOptionsXMLHttpRequest
    ): Promise<any> {
        if (typeof page === 'string') {
            page = this.getPage(page);
        }
        const currentUrl = page.url();
        if (currentUrl.startsWith('https://web.facebook.com') && url.startsWith('https://www.facebook.com')) {
            url = url.replace('https://www.facebook.com', 'https://web.facebook.com');
        }
        const response = await page.evaluate(
            async ({ url, method = 'GET', headers = {}, data = null, withCredentials = true }) => {
                return new Promise((resolve, reject) => {
                    try {
                        const xhr = new XMLHttpRequest();
                        xhr.withCredentials = withCredentials;

                        xhr.open(method, url, true);

                        for (const key in headers) {
                            if (headers.hasOwnProperty(key)) {
                                xhr.setRequestHeader(key, headers[key]);
                            }
                        }

                        xhr.onreadystatechange = () => {
                            if (xhr.readyState === 4) {
                                const status = xhr.status;
                                if (!xhr.responseText) {
                                    reject(new Error('Không có dữ liệu trả về'));
                                    return;
                                }
                                resolve({
                                    status,
                                    data: xhr.responseText
                                });
                            }
                        };

                        xhr.onerror = () => {
                            reject(new Error('Network error'));
                        };

                        if (data && typeof data === 'object' && headers['Content-Type']?.includes('application/json')) {
                            xhr.send(JSON.stringify(data));
                        } else {
                            xhr.send(data);
                        }
                    } catch (err) {
                        reject(err);
                    }
                });
            },
            { url, method, headers, data, withCredentials }
        );
        return response;
    }

    public async evaluateScriptXMLHttpRequestUploadFile(
        page: string | Page,
        {
            url,
            headers = {},
            method = 'POST',
            withCredentials = true
        }: IOptionsXMLHttpRequest,
        formDataInfo: IFormDataInfo[]
    ): Promise<any> {
        if (typeof page === 'string') {
            page = this.getPage(page);
        }
        // 1. Tạo input file và upload file từ hệ thống
        await page.evaluate(() => {
            const input = document.createElement('input');
            input.type = 'file';
            input.id = 'puppeteer-upload';
            document.body.appendChild(input);
        });
        const inputHandle: any = await page.$('#puppeteer-upload');
        if (!inputHandle) {
            throw new Error('Không tìm thấy input file');
        }

        for (const formData of formDataInfo) {
            if (formData.blobValue) {
                // 2. Gán file từ hệ thống người dùng
                await inputHandle.uploadFile(formData.value);
            }
        }

        const response = await page.evaluate(
            async ({ url, method, headers = {}, withCredentials = true, formDataInfo }) => {
                return new Promise((resolve, reject) => {
                    try {
                        const fileInput = document.querySelector<HTMLInputElement>('#puppeteer-upload');
                        if (!fileInput || !fileInput.files || fileInput.files.length === 0) {
                            throw new Error('Không tìm thấy file trong input');
                        }

                        const formData = new FormData();
                        const file = fileInput.files[0];

                        for (const formDataItem of formDataInfo) {
                            if (formDataItem.blobValue) {
                                formData.append(formDataItem.name, file, formDataItem.nameFile);
                                continue;
                            }
                            formData.append(formDataItem.name, formDataItem.value);
                        }

                        const xhr = new XMLHttpRequest();
                        xhr.withCredentials = withCredentials;

                        xhr.open(method, url, true);

                        for (const key in headers) {
                            if (headers.hasOwnProperty(key)) {
                                xhr.setRequestHeader(key, headers[key]);
                            }
                        }

                        xhr.onreadystatechange = () => {
                            if (xhr.readyState === 4) {
                                const status = xhr.status;
                                if (!xhr.responseText) {
                                    reject(new Error('Không có dữ liệu trả về'));
                                    return;
                                }
                                resolve({
                                    status,
                                    data: xhr.responseText
                                });
                            }
                        };

                        xhr.onerror = () => {
                            reject(new Error('Network error'));
                        };

                        xhr.send(formData);
                    } catch (err) {
                        reject(err);
                    }
                });
            },
            { url, method, headers, withCredentials, formDataInfo }
        );
        // Xóa input sau khi dùng xong
        await page.evaluate(() => {
            const input = document.getElementById('puppeteer-upload');
            if (input) {
                input.remove();
            }
        });
        return response;
    }

    public async gotoUrl(
        targetPage: string | Page,
        destinationUrl: string,
        options?: GoToOptions
    ) {
        options = { ...this.defaultOptions, ...options }
        const page = this.resolvePage(targetPage);
        const currentPageUrl = page.url();
        if (currentPageUrl === destinationUrl) {
            await page.reload(options);
            return;
        }
        return await page.goto(destinationUrl, options);
    }

    public async waitForPageNavigation(
        targetPage: string | Page,
        options?: GoToOptions
    ) {
        options = { ...this.defaultOptions, ...options }
        const page = this.resolvePage(targetPage);
        return await page.waitForNavigation(options);
    }

    public async reloadPage(
        targetPage: string | Page,
        options?: GoToOptions
    ) {
        options = { ...this.defaultOptions, ...options };
        const page = this.resolvePage(targetPage);
        return await page.reload(options);
    }

    public async getCurrentUrl(pageId: string): Promise<string> {
        const page = this.getPage(pageId);
        return page.url();
    }

    public async clickElementBySelector(
        pageId: string,
        selector: string,
    ): Promise<void> {
        try {
            const page = this.getPage(pageId);
            await page.evaluate(({ selector }) => {
                const element = document.querySelector(selector);
                if (element) {
                    (element as HTMLElement).click();
                } else {
                    throw new Error(`Không tìm thấy phần tử với selector "${selector}"`);
                }
            }, { selector });
        } catch (error) {
        }
    }

    public async clickElementByText(
        pageId: string,
        tagName: string,
        texts: string[],
        trim: boolean = true
    ): Promise<void> {
        const page = this.getPage(pageId);

        await page.evaluate(
            ({ tagName, texts, trim }) => {
                const elements = Array.from(document.querySelectorAll(tagName));
                const target = elements.find(el => {
                    const content = el.textContent;
                    if (!content) return false;
                    return texts.some(text => trim ? content.trim() === text : content === text);
                });
                if (target) {
                    (target as HTMLElement).click();
                } else {
                    throw new Error(`Không tìm thấy thẻ <${tagName}> với nội dung "${texts.join(', ')}"`);
                }
            },
            { tagName, texts, trim }
        );
    }

    public resolvePage(targetPage: string | Page): Page {
        let activePage: Page;
        if (typeof targetPage === 'string') {
            activePage = this.getPage(targetPage);
        } else {
            activePage = targetPage;
        }
        return activePage;
    }

    public recordNetworkData(
        targetPage: string | Page,
        urlsMapping: string[],
        callback: (data: DataRecordNetworkData) => void
    ) {
        const page = this.resolvePage(targetPage);

        const handler = async (response: HTTPResponse) => {
            try {
                const request = response.request();
                const url = request.url();

                // Lọc URL trước cho tối ưu
                if (!urlsMapping.some(pattern => url.includes(pattern))) return;

                const method = request.method();
                const headers = response.headers();
                const contentType = headers['content-type'] || '';
                const params = Object.fromEntries(new URL(url).searchParams.entries());

                let requestData = null;
                try {
                    requestData = request.postData() ? JSON.parse(request.postData()!) : null;
                } catch {
                    requestData = request.postData();
                }

                // Body có thể fail với binary hoặc cross-origin
                let responseBody: string | null = null;
                try {
                    responseBody = await response.text();
                } catch { }

                callback({
                    url,
                    method,
                    contentType,
                    status: response.status(),
                    requestData,
                    responseBody,
                    params,
                    time: new Date().toISOString()
                });
            } catch (err) {
                console.warn('⚠️ Lỗi recordNetworkData:', err);
            }
        }

        page.on('response', handler);

        return () => {
            page.off('response', handler);
        };
    }
}

export const PuppeteerService = new _PuppeteerService();

export function puppeteerServiceHandlers(win: BrowserWindow) {
    PuppeteerService.reloadSettings();
    ipcMain.on('renderer:reloaded', async () => {
        console.log('Renderer reload → reset PuppeteerService');
        return PuppeteerService.resetPuppeteerService();
    });
    ipcMain.handle('puppeteer:closePage', async (event: IpcMainInvokeEvent, pageId: string) => {
        return PuppeteerService.closePage(pageId);
    });
    ipcMain.handle('puppeteer:captureScreenshot', async (event: IpcMainInvokeEvent, pageId: string) => {
        return PuppeteerService.captureScreenshot(pageId);
    });
    ipcMain.handle('puppeteer:getBrowserIdFromPageId', async (event: IpcMainInvokeEvent, pageId: string) => {
        return PuppeteerService.getBrowserIdFromPageId(pageId);
    });
    ipcMain.handle('puppeteer:evaluateScriptXMLHttpRequest', async (event: IpcMainInvokeEvent, page: string | Page, options: IOptionsXMLHttpRequest) => {
        return PuppeteerService.evaluateScriptXMLHttpRequest(page, options);
    });
    ipcMain.handle('puppeteer:evaluateScriptXMLHttpRequestUploadFile', async (event: IpcMainInvokeEvent, page: string | Page, options: IOptionsXMLHttpRequest, formDataInfo: IFormDataInfo[]) => {
        return PuppeteerService.evaluateScriptXMLHttpRequestUploadFile(page, options, formDataInfo);
    });
    ipcMain.handle('puppeteer:gotoUrl', async (event: IpcMainInvokeEvent, pageId: string, url: string, options?: GoToOptions) => {
        return PuppeteerService.gotoUrl(pageId, url, options);
    });
    ipcMain.handle('puppeteer:getCurrentUrl', async (event: IpcMainInvokeEvent, pageId: string) => {
        return PuppeteerService.getCurrentUrl(pageId);
    });
    ipcMain.handle('puppeteer:clickElementByText', async (event: IpcMainInvokeEvent, pageId: string, tagName: string, texts: string[], trim: boolean = true) => {
        return PuppeteerService.clickElementByText(pageId, tagName, texts, trim);
    });
    ipcMain.handle('puppeteer:clickElementBySelector', async (event: IpcMainInvokeEvent, pageId: string, selector: string) => {
        return PuppeteerService.clickElementBySelector(pageId, selector);
    });
    ipcMain.handle('puppeteer:reloadSettings:puppeteer.delayMs', async (event: IpcMainInvokeEvent) => {
        return PuppeteerService.reloadSettings();
    });
    const mapRecordNetworkDataId: Record<string, () => void> = {};
    ipcMain.handle('puppeteer:recordNetworkData', async (event: IpcMainInvokeEvent, channelTemporary: string, targetPage: string | Page, urlsMapping: string[]) => {
        mapRecordNetworkDataId[channelTemporary] = PuppeteerService.recordNetworkData(targetPage, urlsMapping, (data: DataRecordNetworkData) => {
            event.sender.send(channelTemporary, data);
        });
    });
    ipcMain.handle('puppeteer:recordNetworkData.stop', async (event: IpcMainInvokeEvent, channelTemporary: string) => {
        if (!mapRecordNetworkDataId[channelTemporary]) {
            throw new Error('Không tìm thấy channelTemporary');
        }
        mapRecordNetworkDataId[channelTemporary]();
    });
}
