import { AppDataSource } from "../typeorm.config";
import { AccessListItemEntity } from "../entities/accessListItem.entity";
import { AccessListItem, AccessListType } from "src/models/AccessListItem";
import { ipcMain, IpcMainInvokeEvent } from "electron";

class AccessListItemRepository {
    private getRepoEntities() {
        return AppDataSource.getRepository(AccessListItemEntity);
    }

    public async getAll() {
        const accessListItemRepo = this.getRepoEntities();
        return await accessListItemRepo.find();
    }

    public async addAccessListItem(accessListItem: AccessListItem) {
        const accessListItemRepo = this.getRepoEntities();
        const accessListItemEntity = accessListItemRepo.create({
            name: accessListItem.name,
            type: accessListItem.type,
            textList: accessListItem.list.join('\n'),
        });
        const savedAccessListItemEntity = await accessListItemRepo.save(accessListItemEntity);
        return await this.getAccessListItemById(savedAccessListItemEntity.id);
    }

    public async getAccessListItemById(id: number) {
        const accessListItemRepo = this.getRepoEntities();
        return await accessListItemRepo.findOne({
            where: { id: id },
        });
    }

    public async deleteAccessListItemByIds(ids: number[]) {
        const accessListItemRepo = this.getRepoEntities();
        return await accessListItemRepo.delete(ids);
    }
}

const accessListItemRepository = new AccessListItemRepository();

export function accessListItemRepositoryHandlers(win: Electron.BrowserWindow) {
    ipcMain.handle('database:accessListItem:getAll', async (event: IpcMainInvokeEvent) => {
        return accessListItemRepository.getAll();
    });
    ipcMain.handle('database:accessListItem:addAccessListItem', async (event: IpcMainInvokeEvent, accessListItem: AccessListItem) => {
        return accessListItemRepository.addAccessListItem(accessListItem);
    });
    ipcMain.handle('database:accessListItem:deleteAccessListItemByIds', async (event: IpcMainInvokeEvent, ids: number[]) => {
        return accessListItemRepository.deleteAccessListItemByIds(ids);
    });
}

export default accessListItemRepository;
