import { Column, Entity, JoinTable, ManyToMany, PrimaryGeneratedColumn } from "typeorm";
import { AccountEntity } from "./account.entity";

@Entity({ name: "schedules" })
export class ScheduleEntity {
    @PrimaryGeneratedColumn()
    id!: number;

    @Column({ type: 'varchar', nullable: false })
    schedule_type!: string;

    @Column({ type: "text", nullable: false })
    media!: string;

    @Column({ type: 'varchar', nullable: false })
    status!: string; // Trạng thái (Pending, Running, Completed)

    @Column({ type: "datetime", nullable: false})
    schedule_time: Date;

    @Column({ type: "varchar", length: 255, nullable: false, default: "User" })
    type_account!: string;

    @ManyToMany(() => AccountEntity, (accountEntity) => accountEntity.schedules, {
        onDelete: "CASCADE",
    })
    @JoinTable({
        name: "schedule_accounts", // tên bảng trung gian rõ ràng
        joinColumn: {
            name: "schedule_id",
            referencedColumnName: "id",
        },
        inverseJoinColumn: {
            name: "account_id",
            referencedColumnName: "id",
        },
    })
    accounts: AccountEntity[];

    @Column({ type: "datetime", default: () => "CURRENT_TIMESTAMP" })
    created_at!: Date;

    @Column({ type: "datetime", default: () => "CURRENT_TIMESTAMP", onUpdate: "CURRENT_TIMESTAMP" })
    updated_at!: Date;
}
