import { ipcMain, IpcMainInvokeEvent } from 'electron';
import { RequiredUriUrl, CoreOptions, Response } from "request";
const request = require("request");
import * as fs from "fs";

export function sendRequest(options: RequiredUriUrl & CoreOptions): Promise<Response> {
    if (!options.timeout) {
        options.timeout = 60000;
    }
    if (typeof options.body === 'object') {
        for (const key in options.body) {
            const val = options.body[key];
            if (typeof val === 'string' && val.startsWith('file://')) {
                const pathFile = val.replace('file://', '');
                options.body[key] = fs.createReadStream(pathFile);
            }
        }
    } else if (typeof options.body === 'string') {
        if (options.body.startsWith('file://')) {
            const pathFile = options.body.replace('file://', '');
            options.body = fs.createReadStream(pathFile);
        }
    }
    if (typeof options.formData === 'object') {
        for (const key in options.formData) {
            const val = options.formData[key];
            if (typeof val === 'string' && val.startsWith('file://')) {
                const pathFile = val.replace('file://', '');
                options.formData[key] = fs.createReadStream(pathFile);
            }
        }
    }
    return new Promise((resolve, reject) => {
        request(options, function (error: any, response: Response, body: any) {
            if (error) {
                reject(error);
            } else {
                let responseClone = JSON.parse(JSON.stringify(response));
                resolve(responseClone);
            }
        });
    })
}

function uploadBinary({ url, headers, filePath, proxy }: { url: string, headers: any, filePath: string, proxy?: string }) {
    const options: RequiredUriUrl & CoreOptions = {
        'method': 'POST',
        'url': url,
        'headers': headers,
        body: fs.createReadStream(filePath),
    };
    if (proxy) {
        options.proxy = proxy;
    }
    return sendRequest(options);
}

export function downloadFile(options: RequiredUriUrl & CoreOptions, savePath: string, callbackProgressPercentage: (percent: number) => void) {
    if (!options.timeout) {
        options.timeout = 60000
    }
    const fileStream = fs.createWriteStream(savePath);
    let receivedBytes = 0;
    let totalBytes = 0;

    return new Promise((resolve, reject) => {
        request(options)
            .on('response', (response: Response) => {
                if (response.statusCode === 200) {
                    totalBytes = parseInt(response?.headers['content-length'] || '0', 10);
                } else {
                    reject(new Error(`Failed to download. Status code: ${response.statusCode}`));
                }
            })
            .on('error', (error: any) => {
                reject(error)
            })
            .on('data', (chunk: any) => {
                receivedBytes += chunk.length;
                const percent = (receivedBytes / totalBytes) * 100;
                callbackProgressPercentage(percent);
            })
            .pipe(fileStream)
            .on('close', () => {
                resolve('');
            })
        ;
    })
}

export function requestHandlers(win: Electron.BrowserWindow) {
    ipcMain.handle('send-request', async (event: IpcMainInvokeEvent, options: RequiredUriUrl & CoreOptions) => {
        return sendRequest(options);
    });

    ipcMain.handle('upload-binary', async (event: IpcMainInvokeEvent, options: { url: string, headers: any, filePath: string, proxy?: string }) => {
        return uploadBinary(options);
    });

    ipcMain.on('request:download-file', async (
        event: IpcMainInvokeEvent,
        channelId: string,
        options: RequiredUriUrl & CoreOptions,
        savePath: string
    ) => {
        try {
            await downloadFile(options, savePath, (percent) => {
                event.sender.send(channelId, { status: 'loading', percent });
            });
            event.sender.send(channelId, { status: 'success' });
        } catch (error) {
            event.sender.send(channelId, { status: 'failure', message: (error as Error).message || 'Unknown error' });
        }
    });
}
