import { AppDataSource } from "../typeorm.config";
import { ipcMain, IpcMainInvokeEvent } from "electron";
import { UsedIdEntity } from "../entities/usedIds.entity";
import { UsedId } from "src/models/UsedIdEntity";

class UsedIdRepository {
    private getRepository() {
        return AppDataSource.getRepository(UsedIdEntity);
    }

    public async insert(usedId: UsedId) {
        const usedIdRepo = this.getRepository();
        const usedIdEntity = usedIdRepo.create({
            scope_key: usedId.scopeKey,
            fbid: usedId.fbid,
            type: usedId.type,
            user_id: usedId.userId,
        });
        return await usedIdRepo.save(usedIdEntity)
    }

    public async findOneByKeys(usedId: UsedId) {
        const usedIdRepo = this.getRepository();
        const entity = await usedIdRepo.findOne({
            where: {
                scope_key: usedId.scopeKey,
                fbid: usedId.fbid,
                type: usedId.type,
                user_id: usedId.userId,
            },
        });
        return entity ? UsedId.map(entity) : null;
    }

    public async usedIdIsExist(usedId: UsedId) {
        const usedIdRepo = this.getRepository();
        const count = await usedIdRepo.count({
            where: {
                scope_key: usedId.scopeKey,
                fbid: usedId.fbid,
                type: usedId.type,
                user_id: usedId.userId,
            },
        });
        return count > 0;
    }
}

const usedIdRepository = new UsedIdRepository();

export function usedIdRepositoryHandlers(win: Electron.BrowserWindow) {
    ipcMain.handle('database:usedId:insert', async (event: IpcMainInvokeEvent, usedId: UsedId) => {
        return usedIdRepository.insert(usedId);
    });
    ipcMain.handle('database:usedId:findOneByKeys', async (event: IpcMainInvokeEvent, usedId: UsedId) => {
        return usedIdRepository.findOneByKeys(usedId);
    });
    ipcMain.handle('database:usedId:usedIdIsExist', async (event: IpcMainInvokeEvent, usedId: UsedId) => {
        return usedIdRepository.usedIdIsExist(usedId);
    });
}

export default usedIdRepository;
