import { BrowserWindow, ipcMain, IpcMainInvokeEvent } from "electron";
import { _PuppeteerService, PuppeteerService } from "../PuppeteerService";
import { _FacebookPuppeteer, FacebookPuppeteer } from "./FacebookPuppeteer";
import { Account } from "src/models/Account";
import AppUtils from "../../../utils";

interface UserFb {
    userId: string;
    name?: string;
    gender?: "NEUTER" | "MALE" | "FEMALE" | "UNKNOWN";
}

class _ScanUserInbox  {
    constructor(
        private puppeteerService: _PuppeteerService,
        private facebookPuppeteer: _FacebookPuppeteer
    ) { }

    // Quét danh sách uid nhắn tin cho user [chưa hoàn thành]
    public async scanUserInbox(pageId: string, typeAccount: 'User' | 'Fanpage', account: Account, callback: (usersFb: UserFb[]) => boolean) {
        const page = this.puppeteerService.getPage(pageId);
        console.log("Bắt đầu quét", { typeAccount, account, pageId });
        for(let i = 0; i < 3; i++) {
            await AppUtils.sleep(5000); // fake tiến trình quét
            const listUsersFb: UserFb[] = [ // fake dữ liệu trả về
                { name: "Nguyen Van A", userId: "10001", gender: "NEUTER" },
                { name: "Nguyen Van B", userId: "10002", gender: "MALE" },
            ]
            const isStop = callback(listUsersFb);
            if (isStop) break; // dừng tác vụ
        }
    }
}

export const ScanUserInbox = new _ScanUserInbox(PuppeteerService, FacebookPuppeteer);

export function scanUserInboxHandlers(win: BrowserWindow) {
    let isStopMap: { [key: string]: boolean } = {};

    ipcMain.on('scanUserInbox:stopScanUserInbox', (event: IpcMainInvokeEvent, channelId: string) => {
        isStopMap[channelId] = true;
    });

    ipcMain.on('scanUserInbox:scanUserInbox', async (event: IpcMainInvokeEvent, channelId: string, pageId: string, typeAccount: 'User' | 'Fanpage', account: Account) => {
        try {
            await ScanUserInbox.scanUserInbox(pageId, typeAccount, account, (usersFb: UserFb[]) => {
                event.sender.send(channelId, { status: 'progress', usersFb });
                return isStopMap[channelId];
            });
            event.sender.send(channelId, { status: 'success' });
        } catch (error) {
            event.sender.send(channelId, { status: 'failure', message: (error as Error).message || 'Unknown error' });
        } finally {
            delete isStopMap[channelId];
        }
    });
}
