import { app, BrowserWindow, shell, screen, powerSaveBlocker, session, protocol } from 'electron'
import axios from 'axios';
app.commandLine.appendSwitch('disable-gpu');
app.commandLine.appendSwitch('in-process-gpu');
app.commandLine.appendSwitch('no-sandbox');
app.disableHardwareAcceleration();

import * as path from 'node:path';
import * as fs from "node:fs";
import * as os from 'node:os';
import AppUtils from './utils';
import setupHandlers from './handlers';
import { AppDataSource } from './database/typeorm.config';
import databaseHandlers from './database';
import { scheduleRepository } from './database/repository/schedule.repository';

process.env.APP_ROOT = path.join(__dirname, '..')

let ConfigAppData: any;

if (os.release().startsWith('6.1')) app.disableHardwareAcceleration()
if (process.platform === 'win32') app.setAppUserModelId(app.getName())
if (!app.requestSingleInstanceLock()) {
    app.quit()
    process.exit(0)
}

/** Cấu hình cho chuyển qua bản dev nếu có file config.json trong appData */
try {
    if (!fs.existsSync(path.join(app.getPath('userData'), 'config.json'))) {
        throw new Error('Không tìm thấy file config.json');
    }
    ConfigAppData = JSON.parse(fs.readFileSync(path.join(app.getPath('userData'), 'config.json'), 'utf8'));
    if (!ConfigAppData.productMode && ConfigAppData.urlDev) {
        AppUtils.UrlApp = ConfigAppData.urlDev;
    }
} catch (error) {}

export const VITE_DEV_SERVER_URL = (process as any).env.VITE_DEV_SERVER_URL;

let win: BrowserWindow | null = null;
/** Khởi tạo App */
async function createWindow() {
    const size = screen.getPrimaryDisplay().workAreaSize;
    win = new BrowserWindow({
        x: 0,
        y: 0,
        width: size.width,
        height: size.height,
        title: 'SimpleFacebookProV2',
        webPreferences: {
            preload: path.join(__dirname, 'preload.js'),
            // Warning: Enable nodeIntegration and disable contextIsolation is not secure in production
            nodeIntegration: false,  // Không bật nodeIntegration để tránh XSS
            contextIsolation: true,  // Bật contextIsolation để tăng bảo mật
            webSecurity: false,
            webviewTag: true
        },
    });
    const isRunProductMode = AppUtils.runProductMode();
    if (!isRunProductMode) {
        win.loadURL("http://localhost:4201/");
    } else {
        win.loadURL(`${AppUtils.UrlApp}?t=${Date.now()}`);
    }

    if (ConfigAppData) {
        win?.webContents.openDevTools();
    }

    // Test actively push message to the Electron-Renderer
    win.webContents.on('did-finish-load', () => {
        win?.webContents.send('main-process-message', new Date().toLocaleString())
    })

    win.webContents.on('before-input-event', (event, input) => {
        // Mở DevTools -> Control+Shift+m
        if (input.shift && input.control && input.key.toLowerCase() === 'm') {
            win?.webContents.openDevTools();
            return;
        }
        // Mở AppData -> Control+Shift+p
        if (input.shift && input.control && input.key.toLowerCase() === 'p') {
            let userAppDataPath = app.getPath('userData');
            shell.openExternal(`file://${userAppDataPath}`);
            return;
        }
        // Chặn reload Ctrl+R / Cmd+R để tránh reload lại app mà cho electron load lại index.html khi ở product mode
        if ((input.key === 'r' || input.key === 'R') && (input.control || input.meta)) {
            if (isRunProductMode) {
                event.preventDefault();
                win?.loadURL(`${AppUtils.UrlApp}?t=${Date.now()}`);
            }
        }
    })

    // Make all links open with the browser, not with the application
    win.webContents.setWindowOpenHandler(({ url }) => {
        if (url.startsWith('https:')) shell.openExternal(url)
        return { action: 'deny' }
    })
    setupHandlers(win);
    databaseHandlers(win);
    const id = powerSaveBlocker.start('prevent-display-sleep');
}

app.whenReady().then(async () => {
    const filter = {
        urls: ['*://*/*'], // Lọc tất cả các tài nguyên
    };
    session.defaultSession.webRequest.onBeforeSendHeaders(filter, (details, callback) => {
        const url = details.url;
        const listOrigin = [
            'facebook', 'instagram', 'threads'
        ];
        if (listOrigin.some(origin => url.includes(origin))) {
            details.requestHeaders['Origin'] = 'https://www.facebook.com/';
        }
        callback({ requestHeaders: details.requestHeaders })
    });
    const currentSession = session.defaultSession;
    try {
        await currentSession.clearCache();
    } catch (err: any) {
        AppUtils.logDebugging('Lỗi khi xóa cache:', err.message);
    }

    protocol.registerBufferProtocol('avatar-fb', async (request, respond) => {
        try {
            const userId = request.url.replace('avatar-fb://', '');
            const res = await axios.get(
                `https://graph.facebook.com/${userId}/picture?height=500&width=500&access_token=6628568379%7Cc1e620fa708a1d5696fb991c1bde5662`,
                { responseType: 'arraybuffer' }
            );
            respond({
                mimeType: 'image/jpeg',
                data: Buffer.from(res.data)
            });
        } catch (err) {
            respond({ statusCode: 404 });
        }
    });
    
    // Create Window
    try {
        await AppDataSource.initialize();
        console.log("Kết nối database thành công!");
        const migrations = await AppDataSource.runMigrations();
        console.log("Migrations have been run successfully!", migrations);
        scheduleRepository.interruptExpiredRunningSchedules();
    } catch (error) {
        console.error("Lỗi kết nối database:", error);
    }
    createWindow();
});

app.on('window-all-closed', () => {
    win = null
    if (process.platform !== 'darwin') app.quit()
})

app.on('second-instance', () => {
    if (win) {
        // Focus on the main window if the user tried to open another
        if (win.isMinimized()) win.restore()
        win.focus()
    }
})

app.on('activate', () => {
    const allWindows = BrowserWindow.getAllWindows()
    if (allWindows.length) {
        allWindows[0].focus()
    } else {
        createWindow()
    }
})
