import { ipcMain, IpcMainInvokeEvent, BrowserWindow, app, shell } from "electron";
import pathNode from "node:path";
import fsNode from "node:fs";
import AppUtils from "../utils";
const fsExtra = require("fs-extra");
const crypto = require("crypto");

class FileHandler {
    public mkdir(path: string, options?: fsNode.Mode | fsNode.MakeDirectoryOptions | null | undefined): Promise<void> {
        return new Promise((resolve, reject) => {
            fsNode.mkdir(path, options, (err) => {
                if (err) {
                    reject(err);
                } else {
                    resolve();
                }
            });
        });
    }

    public appendFile(filePath: string, data: string): Promise<void> {
        return new Promise((resolve, reject) => {
            fsNode.appendFile(filePath, data, (err) => {
                if (err) {
                    reject(err);
                } else {
                    resolve();
                }
            });
        });
    }

    public writeFile(filePath: string, data: string | Buffer): Promise<void> {
        return new Promise((resolve, reject) => {
            fsNode.writeFile(filePath, data, (err) => {
                if (err) {
                    reject(err);
                } else {
                    resolve();
                }
            });
        });
    }

    public async appendTextToFile(filePath: string, data: string) {
        const fullPath = pathNode.resolve(filePath);
        const dir = pathNode.dirname(fullPath);
        if (!fsNode.existsSync(dir)) {
            await this.mkdir(dir, { recursive: true });
        }
        return this.appendFile(fullPath, data);
    }

    public async readFile(filePath: string, options?: {
        encoding?: null | undefined;
        flag?: string | undefined;
    } | null): Promise<string | Buffer> {
        return new Promise((resolve, reject) => {
            fsNode.readFile(filePath, options, (err, data) => {
                if (err) {
                    reject(err);
                } else {
                    resolve(data);
                }
            });
        });
    }

    /** Lấy thông tin file */
    public async stat(filePath: string) {
        return new Promise((resolve, reject) => {
            fsNode.stat(filePath, (err, stats) => {
                if (err) {
                    reject(err);
                } else {
                    resolve(stats);
                }
            });
        });
    }

    /** Xem file trong thư mục */
    public openFile(filePath: string): Promise<string> {
        return shell.openPath(filePath);
    }

    /** Mở file trong thư mục */
    public showItemInFolder(filePath: string) {
        return shell.showItemInFolder(filePath);
    }

    /** Copy file với fs-extra */
    public async copyFileFsExtra(src: string, dest: string): Promise<void> {
        return fsExtra.copy(src, dest);
    }

    /** Lấy tên file theo platform */
    public async getFileNameByPlatform(pathFile: string, platform: 'darwin' | 'win32' | 'linux') {
        if (platform === 'darwin' || platform === 'linux') {
            return pathNode.posix.basename(pathFile);
        } else if (platform === 'win32') {
            return pathNode.win32.basename(pathFile);
        } else {
            throw new Error(`Platform không hỗ trợ ${platform}`);
        }
    }

    /** Đổi tên thư mục */
    public async renameFolder(oldPath: string, newPath: string) {
        return await fsExtra.move(oldPath, newPath, { overwrite: false });
    }

    /** Xoá file */
    public async unlink(filePath: string): Promise<void> {
        return new Promise((resolve, reject) => {
            fsNode.unlink(filePath, (err) => {
                if (err) {
                    reject(err);
                } else {
                    resolve();
                }
            });
        });
    }

    /** Kiểm tra file có tồn tại hay không */
    public existsSync(filePath: string): boolean {
        return fsNode.existsSync(filePath);
    }

    /**
     * Gộp các file chunk thành 1 file hoàn chỉnh
     * @param {string[]} chunkPaths - mảng đường dẫn chunk (đúng thứ tự)
     * @param {string} outputPath - đường dẫn file sau khi gộp
     */
    public async mergeChunks(chunkPaths: string[], outputPath: string): Promise<void> {
        return new Promise((resolve, reject) => {
            const writeStream = fsNode.createWriteStream(outputPath);
            const appendChunk = (index: number) => {
                if (index >= chunkPaths.length) {
                    writeStream.end();
                    return resolve();
                }
                const readStream = fsNode.createReadStream(chunkPaths[index]);
                readStream.pipe(writeStream, { end: false });
                readStream.on('end', () => {
                    appendChunk(index + 1);
                });
                readStream.on('error', reject);
            };
            appendChunk(0);
        });
    }
}

export const fileHandler = new FileHandler();

export function fsHandlers(win: BrowserWindow) {
    /** Lấy tên file */
    ipcMain.handle('path:basename', async (event: IpcMainInvokeEvent, path: string) => {
        return pathNode.basename(path);
    });

    /** Lấy đường dẫn userData */
    ipcMain.handle('app:userData', async (event: IpcMainInvokeEvent) => {
        return app.getPath('userData');
    });

    /** Lấy đường dẫn join */
    ipcMain.handle('path:join', async (event: IpcMainInvokeEvent, ...args: string[]) => {
        return pathNode.join(...args);
    });

    /** Ghi file */
    ipcMain.handle('fs:writeFile', async (event: IpcMainInvokeEvent, path: string, data: any) => {
        const buffer = AppUtils.normalizeToBuffer(data);
        return fileHandler.writeFile(path, buffer);
    });

    /** Tạo folder */
    ipcMain.handle('fs:mkdir', async (event: IpcMainInvokeEvent, path: string, options?: any) => {
        return fileHandler.mkdir(path, options);
    });

    /** Kiểm tra file có tồn tại hay không */
    ipcMain.handle('fs:existsSync', async (event: IpcMainInvokeEvent, path: string) => {
        return fsNode.existsSync(path);
    });

    /** Tạo stream để đọc file */
    ipcMain.handle('fs:createReadStream', async (event: IpcMainInvokeEvent, path: string) => {
        return fsNode.createReadStream(path);
    });

    /** Đọc file */
    ipcMain.handle('fs:readFileSync', async (event: IpcMainInvokeEvent, path: string, ...args: any[]) => {
        const data = fsNode.readFileSync(path, ...args);
        return data;
    });

    /** Xóa file */
    ipcMain.handle('fs:unlinkSync', async (event: IpcMainInvokeEvent, path: string) => {
        return fsNode.unlinkSync(path);
    });

    /** Mở một URL trong trình duyệt */
    ipcMain.handle('shell:openExternal', async (event: IpcMainInvokeEvent, url: string) => {
        return shell.openExternal(url);
    });

    /** Lấy phần mở rộng của file */
    ipcMain.handle('path:extname', async (event: IpcMainInvokeEvent, path: string) => {
        return pathNode.extname(path);
    });

    /** Lấy ra đường dẫn thư mục chứa file */
    ipcMain.handle('path:dirname', async (event: IpcMainInvokeEvent, path: string) => {
        return pathNode.dirname(path);
    });

    /** Đọc folder trả về ds tên file trong folder */
    ipcMain.handle('fs:readdirSync', async (event: IpcMainInvokeEvent, pathFolder: string) => {
        return fsNode.readdirSync(pathFolder);
    });

    /** Ghi nối data vào file theo filePath  */
    ipcMain.handle('fs:appendFileSync', async (event: IpcMainInvokeEvent, filePath: string, data: string) => {
        return fsNode.appendFileSync(filePath, data);
    });

    /** Xóa folder */
    ipcMain.handle('fsExtra:removeSync', async (event: IpcMainInvokeEvent, pathFolder: string) => {
        return fsExtra.removeSync(pathFolder);
    });

    /** Sao chép file */
    ipcMain.handle('fs:copyFile', async (event: IpcMainInvokeEvent, pathFile: string, newPathFile: string) => {
        return fsExtra.copyFileSync(pathFile, newPathFile);
    });

    ipcMain.handle('crypto:hashMd5File', async (event, pathFile: string) => {
        const content = fsNode.readFileSync(pathFile);
        return crypto.createHash('md5').update(content).digest('hex');
    });

    ipcMain.handle('crypto:createHmac', async (event, key: string, data: string) => {
        return crypto.createHmac('sha256', key).update(data).digest('hex');
    });

    /** Ghi nối data vào file theo filePath */
    ipcMain.handle('fs:appendTextToFile', async (event, filePath: string, data: string) => {
        return fileHandler.appendTextToFile(filePath, data);
    });

    /** Lấy thông tin file */
    ipcMain.handle('fs:stat', async (event, filePath: string) => {
        return fileHandler.stat(filePath);
    });

    /** Xem file trong thư mục */
    ipcMain.handle('fs:openFile', async (event, filePath: string) => {
        return fileHandler.openFile(filePath);
    });

    /** Mở file trong thư mục */
    ipcMain.handle('fs:showItemInFolder', async (event, filePath: string) => {
        return fileHandler.showItemInFolder(filePath);
    });

    /** Sao chép file với fs-extra */
    ipcMain.handle('fs:copyFileFsExtra', async (event, pathFile: string, newPathFile: string) => {
        return fileHandler.copyFileFsExtra(pathFile, newPathFile);
    });

    /** Lấy tên file theo platform */
    ipcMain.handle('fs:getFileNameByPlatform', async (event, pathFile: string, platform: 'darwin' | 'win32' | 'linux') => {
        return fileHandler.getFileNameByPlatform(pathFile, platform);
    });

    /** Đổi tên thư mục */
    ipcMain.handle('fs:renameFolder', async (event, oldPath: string, newPath: string) => {
        return fileHandler.renameFolder(oldPath, newPath);
    });

    /** Đổi tên thư mục */
    ipcMain.handle('fs:mergeChunks', async (event, chunkPaths: string[], outputPath: string) => {
        return fileHandler.mergeChunks(chunkPaths, outputPath);
    });
}