import { Post } from "src/models/Post";
import { PostEntity } from "../entities/post.entity";
import { AppDataSource } from "../typeorm.config";
import { ipcMain, IpcMainInvokeEvent } from "electron";
import { In, IsNull, Not } from "typeorm";

class PostRepository {
    private getRepoEntities() {
        return AppDataSource.getRepository(PostEntity);
    }
    public async getAll() {
        const postRepo = this.getRepoEntities();
        return await postRepo.find({ relations: { category: true } });
    }
    public async getPostByIds(ids: number[]) {
        const postRepo = this.getRepoEntities();
        return await postRepo.find({
            where: { id: In(ids) },
            relations: ["category"],
        });
    }
    public async addPost(post: Post) {
        const postRepo = this.getRepoEntities();
        const categoryEntity = postRepo.create({
            title: post.title,
            content: post.content,
            media: post.media,
            category: post.category?.id ? { id: post.category.id } : null,
        });
        const savedPost = await postRepo.save(categoryEntity);
        return await this.getPostById(savedPost.id);
    }
    public async updatePost(id: number, post: Post) {
        const postRepo = this.getRepoEntities();
        return await postRepo.update(id, {
            title: post.title,
            content: post.content,
            media: post.media,
            category: post.category?.id ? { id: post.category.id } : null,
        });
    }
    public async updateContentPosts(ids: number[], content: string) {
        const postRepo = this.getRepoEntities();
        return await postRepo.update(ids, {
            content: content,
        });
    }
    public async deletePostByIds(ids: number[]) {
        const postRepo = this.getRepoEntities();
        return await postRepo.delete(ids);
    }
    public async getPostById(id: number) {
        const postRepo = this.getRepoEntities();
        return await postRepo.findOne({
            where: { id: id },
            relations: ["category"], // Load quan hệ category_post
        });
    }

    /** Lấy toàn bộ post có đường dẫn media là không null */
    public async getPostByMedia(): Promise<PostEntity[]> {
        const postRepo = this.getRepoEntities();
        const posts = await postRepo.find({
            where: { media: Not(IsNull()) },
        });
        return posts;
    }

    /** Cập nhật đường dẫn media của post */
    public async updateMediaPost(id: number, media: string) {
        const postRepo = this.getRepoEntities();
        return await postRepo.update(id, { media: media });
    }
}
const postRepository = new PostRepository();

export function postRepositoryHandlers(win: Electron.BrowserWindow) {
    ipcMain.handle('database:post:getAll', async (event: IpcMainInvokeEvent) => {
        return postRepository.getAll();
    });
    ipcMain.handle('database:post:getPostByIds', async (event: IpcMainInvokeEvent, ids: number[]) => {
        return postRepository.getPostByIds(ids);
    });
    ipcMain.handle('database:post:addPost', async (event: IpcMainInvokeEvent, post: Post) => {
        return postRepository.addPost(post);
    });
    ipcMain.handle('database:post:updatePost', async (event: IpcMainInvokeEvent, id: number, post: Post) => {
        return postRepository.updatePost(id, post);
    });
    ipcMain.handle('database:post:deletePostByIds', async (event: IpcMainInvokeEvent, ids: number[]) => {
        return postRepository.deletePostByIds(ids);
    });
    ipcMain.handle('database:post:updateContentPosts', async (event: IpcMainInvokeEvent, ids: number[], content: string) => {
        return postRepository.updateContentPosts(ids, content);
    });
    ipcMain.handle('database:post:getPostByMedia', async (event: IpcMainInvokeEvent) => {
        return postRepository.getPostByMedia();
    });
    ipcMain.handle('database:post:updateMediaPost', async (event: IpcMainInvokeEvent, id: number, media: string) => {
        return postRepository.updateMediaPost(id, media);
    });
}

export default postRepository;
