import { HistoryTask } from "src/models/HistoryTask";
import { HistoryTaskEntity } from "../entities/historyTask.entity";
import { AppDataSource } from "../typeorm.config";
import { ipcMain, IpcMainInvokeEvent } from "electron";

class HistoryTaskRepository {
    private getRepository() {
        return AppDataSource.getRepository(HistoryTaskEntity);
    }

    public async getHistoryByUserId(userId: string) {
        const historyTaskRepo = this.getRepository();
        return await historyTaskRepo.find({
            where: {
                user_id: userId
            },
            order: {
                created_at: "DESC"
            }
        });
    }

    public async addHistoryTask(historyTask: HistoryTask) {
        const historyTaskRepo = this.getRepository();
        return await historyTaskRepo.save({
            user_id: historyTask.userId,
            task_type: historyTask.taskType,
            history: historyTask.history
        });
    }

    public async getHistoryByUserIdAndTaskType(userId: string, taskType?: string) {
        const historyTaskRepo = this.getRepository();
        const whereCondition: any = { user_id: userId };
        if (taskType !== undefined) {
            whereCondition.task_type = taskType;
        }
        return await historyTaskRepo.find({
            where: whereCondition,
            order: {
                created_at: "DESC"
            }
        });
    }

    public async getAllHistoryByTaskType(taskType?: string) {
        const historyTaskRepo = this.getRepository();
        const whereCondition: any = {};
        if (taskType !== undefined) {
            whereCondition.task_type = taskType;
        }
        return await historyTaskRepo.find({
            where: whereCondition,
            order: {
                created_at: "DESC"
            }
        });
    }

    public async deleteHistoryByUserId(userId: string) {
        const historyTaskRepo = this.getRepository();
        return await historyTaskRepo.delete({ user_id: userId });
    }

    public async deleteHistoryByUserIdAndTaskType(userId: string, taskType: string) {
        const historyTaskRepo = this.getRepository();
        return await historyTaskRepo.delete({ user_id: userId, task_type: taskType });
    }

    public async deleteByIds(ids: number[]) {
        const historyTaskRepo = this.getRepository();
        return await historyTaskRepo.delete(ids);
    }
}

const historyTaskRepository = new HistoryTaskRepository();

export function historyTaskRepositoryHandlers(win: Electron.BrowserWindow) {
    ipcMain.handle('database:history-task:getHistoryByUserId', async (event: IpcMainInvokeEvent, userId: string) => {
        return historyTaskRepository.getHistoryByUserId(userId);
    });
    ipcMain.handle('database:history-task:addHistoryTask', async (event: IpcMainInvokeEvent, historyTask: HistoryTask) => {
        return historyTaskRepository.addHistoryTask(historyTask);
    });
    ipcMain.handle('database:history-task:getHistoryByUserIdAndTaskType', async (event: IpcMainInvokeEvent, userId: string, taskType?: string) => {
        return historyTaskRepository.getHistoryByUserIdAndTaskType(userId, taskType);
    });
    ipcMain.handle('database:history-task:deleteHistoryByUserId', async (event: IpcMainInvokeEvent, userId: string) => {
        return historyTaskRepository.deleteHistoryByUserId(userId);
    });
    ipcMain.handle('database:history-task:deleteHistoryByUserIdAndTaskType', async (event: IpcMainInvokeEvent, userId: string, taskType: string) => {
        return historyTaskRepository.deleteHistoryByUserIdAndTaskType(userId, taskType);
    });
    ipcMain.handle('database:history-task:getAllHistoryByTaskType', async (event: IpcMainInvokeEvent, taskType?: string) => {
        return historyTaskRepository.getAllHistoryByTaskType(taskType);
    });
    ipcMain.handle('database:history-task:deleteByIds', async (event: IpcMainInvokeEvent, ids: number[]) => {
        return historyTaskRepository.deleteByIds(ids);
    });
}
