import { Entity, PrimaryGeneratedColumn, Column, ManyToOne, JoinColumn, Relation, ManyToMany, JoinTable, OneToMany } from "typeorm";
import { ProxyEntity } from "./proxy.entity";
import { CategoryEntity } from "./category.entity";
import { ScriptEntity } from "./script.entity";
import { AccessListItemEntity } from "./accessListItem.entity";
import { ScheduleEntity } from "./schedule.entity";

@Entity({ name: "accounts" })
export class AccountEntity {
    @PrimaryGeneratedColumn()
    id!: number;

    @Column({ type: "varchar", length: 255, nullable: true })
    name!: string;

    @Column({ type: "text", nullable: true })
    cookie!: string;

    @Column({ type: "varchar", length: 5, nullable: true })
    live!: string;

    @Column({ type: "varchar", length: 255, nullable: true })
    user_agent!: string;

    @Column({ type: "varchar", length: 255, nullable: true })
    code2fa!: string;

    @Column({ type: "varchar", length: 255, nullable: true })
    user_id!: string;

    @Column({ type: "varchar", length: 255, nullable: true })
    username!: string;

    @Column({ type: "varchar", length: 255, nullable: true })
    email!: string;

    @Column({ type: "varchar", length: 255, nullable: true })
    pass_email!: string;

    @Column({ type: "varchar", length: 255, nullable: true })
    password!: string;

    @Column({ type: "varchar", length: 255, nullable: true })
    path_profile!: string; // đường dẫn đến thư mục profile của tài khoản được sử dụng để sử dụng chung profile với v1 hạn chế cho chỉnh sửa

    @Column({ type: "varchar", length: 255, nullable: false, default: "User" })
    type_account!: string;

    @Column({ type: "varchar", length: 255, nullable: true })
    delegate_page_id!: string;

    // Self-referencing relationship - Parent account
    @ManyToOne(() => AccountEntity, (account) => account.fanpage_accounts, { nullable: true, onDelete: "CASCADE" })
    @JoinColumn({ name: "user_owner" })
    user_owner!: Relation<AccountEntity | null>;

    // Self-referencing relationship - Child accounts
    @OneToMany(() => AccountEntity, (account) => account.user_owner, { onDelete: "CASCADE" })
    fanpage_accounts!: AccountEntity[];

    @ManyToOne(() => ProxyEntity, (proxy) => proxy.accounts, { nullable: true, onDelete: "SET NULL" })
    @JoinColumn({ name: "proxy_id" })
    proxy!: Relation<ProxyEntity | null>;

    @ManyToOne(() => CategoryEntity, (category) => category.accounts, { nullable: true, onDelete: "SET NULL" })
    @JoinColumn({ name: "category_id" })
    category!: Relation<CategoryEntity | null>;

    @ManyToMany(() => ScriptEntity, (scriptEntity) => scriptEntity.accounts, {
        onDelete: "CASCADE",
    })
    @JoinTable({
        name: "account_scripts",
        joinColumn: {
            name: "account_id",
            referencedColumnName: "id",
        },
        inverseJoinColumn: {
            name: "script_id",
            referencedColumnName: "id",
        },
    })
    scripts: ScriptEntity[];

    @ManyToMany(() => ScheduleEntity, (schedule) => schedule.accounts)
    schedules!: ScheduleEntity[];

    @ManyToMany(() => AccessListItemEntity, (accessListItemEntity) => accessListItemEntity.accounts, {
        onDelete: "CASCADE",
    })
    @JoinTable({
        name: "account_access_list_items",
        joinColumn: {
            name: "account_id",
            referencedColumnName: "id",
        },
        inverseJoinColumn: {
            name: "access_list_item_id",
            referencedColumnName: "id",
        },
    })
    accessListItem: AccessListItemEntity[];

    @Column({ type: "datetime", default: () => "CURRENT_TIMESTAMP" })
    created_at!: Date;

    @Column({ type: "datetime", default: () => "CURRENT_TIMESTAMP", onUpdate: "CURRENT_TIMESTAMP" })
    updated_at!: Date;
}
