import { BrowserWindow, ipcMain, IpcMainInvokeEvent } from "electron";
import { _PuppeteerService, PuppeteerService } from "../PuppeteerService";
import { _FacebookPuppeteer, FacebookPuppeteer } from "./FacebookPuppeteer";
import { Account } from "src/models/Account";
import AppUtils from "../../../utils";
import { ElementHandle } from "puppeteer";

class _SendInboxFriends {
    constructor(
        private puppeteerService: _PuppeteerService,
        private facebookPuppeteer: _FacebookPuppeteer
    ) { }

    /** Hàm xử lý gửi tin nhắn cho 1 user id */
    public async sendInboxFriends(pageId: string, account: Account, userId: string, taskSetting: any) {
        const page = this.puppeteerService.getPage(pageId);
        const { contentInbox, pathPhotos = [] } = taskSetting;

        // Đi đến trang chat
        await this.puppeteerService.gotoUrl(page, `https://www.facebook.com/messages/t/${userId}`);

        // Xử lý dialog xác thực nếu có (theo logic Selenium gốc)
        try {
            await page.waitForSelector("input[autocomplete='one-time-code']", { timeout: 5000 });
            console.log('🔐 Phát hiện dialog xác thực OTP');

            // Đóng dialog theo logic Selenium gốc
            let dialogs = await page.$$("div[role='dialog']");
            if (dialogs.length > 0) {
                const lastDialog = dialogs[dialogs.length - 1];
                const closeButton = await lastDialog.$("div[role='button']");
                if (closeButton) {
                    // Sử dụng executeScript để click như Selenium
                    await page.evaluate((element) => {
                        element.click();
                    }, closeButton);
                    console.log('✅ Đã đóng dialog xác thực');
                    await new Promise(resolve => setTimeout(resolve, 3000));
                }
                await new Promise(resolve => setTimeout(resolve, 5000));

                // Tìm lại dialogs sau khi đóng
                dialogs = await page.$$("div[role='dialog']");
                if (dialogs.length > 0) {
                    let dialogNotAsync = dialogs[dialogs.length - 1];

                    // Click button thứ 4 (index 3) để tiếp tục
                    const allButtons = await dialogNotAsync.$$("div[role='button']");
                    console.log(`Tìm thấy ${allButtons.length} button trong dialog xác thực`);
                    if (allButtons.length > 3) {
                        await page.evaluate((element) => {
                            element.click();
                        }, allButtons[3]);
                        console.log('✅ Đã click button thứ 4 (index 3) - không khôi phục');
                        await new Promise(resolve => setTimeout(resolve, 3000));
                    }
                }
            }
        } catch (e) {
            console.log('✅ Không có dialog xác thực');
        }

        // Tìm main element
        let roleMain = await this.checkMainInbox(page);
        let inputChat = await roleMain.$$("div[contenteditable='true']");

        // Nếu không tìm thấy input chat, xử lý button "Tiếp tục"
        if (inputChat.length === 0) {
            const allButtons = await roleMain.$$("div[role='button']");
            for (const btn of allButtons) {
                const btnText = await btn.evaluate((el: any) => el.innerText.trim());
                if (btnText.includes('Tiếp tục') || btnText.includes('Continue')) {
                    await new Promise(resolve => setTimeout(resolve, 3000));
                    await btn.click({ clickCount: 2 });
                    await new Promise(resolve => setTimeout(resolve, 3000));
                    break;
                }
            }

            // Thử lại tìm input chat
            roleMain = await this.checkMainInbox(page);
            inputChat = await roleMain.$$("div[contenteditable='true']");

            // Nếu vẫn không có, thử các cách khác
            if (inputChat.length === 0) {
                const pageSource = await page.content();
                if (pageSource.includes('facebook.com/help')) {
                    await page.goBack();
                    await new Promise(resolve => setTimeout(resolve, 3000));

                    roleMain = await this.checkMainInbox(page);
                    const allButtons = await roleMain.$$("div[role='button']");
                    for (const btn of allButtons) {
                        const btnText = await btn.evaluate((el: any) => el.innerText.trim());
                        if (btnText.includes('Tiếp tục') || btnText.includes('Continue')) {
                            await new Promise(resolve => setTimeout(resolve, 3000));
                            await btn.click({ clickCount: 2 });
                            await new Promise(resolve => setTimeout(resolve, 3000));
                            break;
                        }
                    }
                    roleMain = await this.checkMainInbox(page);
                }
            }

            inputChat = await roleMain.$$("div[contenteditable='true']");

            // Thử click button đầu tiên và cuối cùng
            if (inputChat.length === 0) {
                const allButtons = await roleMain.$$("div[role='button']");
                if (allButtons.length > 0) {
                    await allButtons[0].click({ clickCount: 2 });
                    await new Promise(resolve => setTimeout(resolve, 3000));

                    roleMain = await this.checkMainInbox(page);
                    inputChat = await roleMain.$$("div[contenteditable='true']");

                    if (inputChat.length === 0) {
                        await allButtons[allButtons.length - 1].click({ clickCount: 2 });
                        await new Promise(resolve => setTimeout(resolve, 3000));
                        roleMain = await this.checkMainInbox(page);
                    }
                }
            }
        }

        // Tìm input chat từ toàn bộ page nếu không tìm thấy trong roleMain
        inputChat = await roleMain.$$("div[contenteditable='true']");
        if (inputChat.length === 0) {
            inputChat = await page.$$("div[contenteditable='true']");
        }
        if (inputChat.length === 0) {
            throw new Error(`Không thể gửi tin nhắn đến ${userId}. (no input found)`);
        }
        // Upload ảnh nếu có
        if (pathPhotos && pathPhotos.length > 0) {
            for (const imagePath of pathPhotos) {
                const fileInputs = await roleMain.$$("input[type='file']");
                if (fileInputs.length > 0) {
                    await fileInputs[0].uploadFile(imagePath);
                    await new Promise(resolve => setTimeout(resolve, 3000));
                }
            }
        }

        // Nhập nội dung vào input chat
        await this.sendKeyContentEditor(page, inputChat[0], AppUtils.spinText(contentInbox));
        await new Promise(resolve => setTimeout(resolve, 3000));

        // Gửi tin nhắn
        await page.keyboard.press('Enter');
    }

    private async checkMainInbox(page: any) {
        const roleMains = await page.$$("div[role='main']");
        if (roleMains.length > 0) {
            return roleMains[roleMains.length - 1];
        } else {
            const htmlDiv = await page.$(".html-div");
            return htmlDiv || page;
        }
    }

    private async sendKeyContentEditor(page: any, element: any, content: string) {
        // Click vào element trước
        await element.click();
        await new Promise(resolve => setTimeout(resolve, 7000));

        // Clear nội dung hiện tại
        await element.evaluate((el: any) => el.innerText = '');

        // Type nội dung mới
        await element.type(content);
    }

    public async sendInboxFriendsByFanpage(pageId: string, account: Account, userId: string, taskSetting: any) {
        const page = this.puppeteerService.getPage(pageId);
        const { contentInbox, pathPhotos = [] } = taskSetting;
        // Đi đến trang chat
        await this.puppeteerService.gotoUrl(page, `https://business.facebook.com/latest/inbox/all/?nav_ref=manage_page_ap_plus_inbox_message_button&asset_id=${account.delegatePageId}&mailbox_id=&selected_item_id=${userId}&thread_type=FB_MESSAGE`);
        await new Promise(resolve => setTimeout(resolve, 3000));
        const selectorInput = 'div[contenteditable="true"][role="textbox"]'; // 'textarea[type="text"]';
        let textarea: ElementHandle | null = null;
        try {
            textarea = await page.waitForSelector(selectorInput, { timeout: 10000 });
        } catch (err) {
            throw new Error(`Không thể gửi tin nhắn đến ${userId}. (no textarea found)`);
        }
        if (!textarea) {
            throw new Error(`Không thể gửi tin nhắn đến ${userId}. (no textarea found)`);
        }
        if (pathPhotos && pathPhotos.length > 0) {
            await this.simulateFileDragAndDrop(page, selectorInput, pathPhotos);
            await new Promise(resolve => setTimeout(resolve, 10000));
        }
        await page.evaluate((selector) => {
            const el: any = document.querySelector(selector);
            if (!el) return;
            el.focus();
            document.execCommand('selectAll', false, '');
            document.execCommand('delete', false, '');
        }, selectorInput);
        const text = AppUtils.spinText(contentInbox);
        await textarea.focus();
        for (const char of text) {
            if (char === '\n') {
                await page.keyboard.down('Shift');
                await page.keyboard.press('Enter');
                await page.keyboard.up('Shift');
            } else {
                await textarea.type(char);
            }
        }
        if (pathPhotos && pathPhotos.length > 0) {
            await page.waitForFunction(() => {
                return document.querySelectorAll('div[data-visualcompletion="loading-state"]').length === 0;
            }, { timeout: 60000 });
        }
        await page.keyboard.press('Enter');
    }

    private async simulateFileDragAndDrop(page: any, dropSelector: string, filePaths: string[]) {
        for (const filePath of filePaths) {
            const tempInputId = 'puppeteerTempFileInput' + Date.now();

            // 1️⃣ Tạo input tạm
            await page.evaluate((id: string) => {
                const input = document.createElement('input');
                input.type = 'file';
                input.id = id;
                input.multiple = true; // cho phép chọn nhiều file nếu cần
                input.style.display = 'none';
                document.body.appendChild(input);
            }, tempInputId);

            // 2️⃣ Upload file
            const tempFileInput = await page.$(`#${tempInputId}`);
            await tempFileInput.uploadFile(filePath); // chỉ 1 file mỗi lượt
            const dropZoneElement = await page.$(dropSelector);

            // 3️⃣ Thực thi mô phỏng drag-drop trong browser context
            const success = await page.evaluate((tempInputId: string, dropZone: any) => {
                const tempInput: any = document.getElementById(tempInputId);
                if (!tempInput || !tempInput.files.length) {
                    console.error('Không có file nào được chọn.');
                    if (tempInput) document.body.removeChild(tempInput);
                    return false;
                }

                const files = tempInput.files;
                const dataTransfer = new DataTransfer();
                for (let i = 0; i < files.length; i++) {
                    dataTransfer.items.add(files[i]);
                }

                const dragEnter = new DragEvent('dragenter', { bubbles: true, cancelable: true, dataTransfer });
                const dragOver = new DragEvent('dragover', { bubbles: true, cancelable: true, dataTransfer });
                const drop = new DragEvent('drop', { bubbles: true, cancelable: true, dataTransfer });

                dropZone.dispatchEvent(dragEnter);
                dropZone.dispatchEvent(dragOver);
                dropZone.dispatchEvent(drop);

                document.body.removeChild(tempInput);
                return true;
            }, tempInputId, dropZoneElement);

            if (!success) {
                console.error(`❌ Giả lập kéo thả file thất bại: ${filePath}`);
            } else {
                console.log(`✅ Đã kéo thả thành công: ${filePath}`);
            }

            // 4️⃣ Chờ Facebook load preview (tránh gửi khi ảnh chưa hiện)
            await new Promise(resolve => setTimeout(resolve, 2000));
        }
    }
}

export const SendInboxFriends = new _SendInboxFriends(PuppeteerService, FacebookPuppeteer);

export function sendInboxFriendsHandlers(win: BrowserWindow) {
    ipcMain.handle('sendInboxFriends:sendInboxFriends', async (event: IpcMainInvokeEvent, pageId: string, typeAccount: 'User' | 'Fanpage', account: Account, userId: string, taskSetting: any) => {
        if (typeAccount === 'Fanpage') {
            return SendInboxFriends.sendInboxFriendsByFanpage(pageId, account, userId, taskSetting);
        }
        return SendInboxFriends.sendInboxFriends(pageId, account, userId, taskSetting);
    });
}
